CREATE TABLE `answer_record` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '答题记录ID',
  `user_id` bigint NOT NULL COMMENT '用户ID',
  `question_id` bigint NOT NULL COMMENT '题目ID',
  `user_answer` varchar(255) NOT NULL COMMENT '用户答案',
  `is_correct` tinyint NOT NULL COMMENT '是否正确：1正确，0错误',
  `answered_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '答题时间',
  PRIMARY KEY (`id`),
  KEY `idx_answer_user` (`user_id`),
  KEY `idx_answer_question` (`question_id`),
  KEY `idx_answer_user_time` (`user_id`,`answered_at`),
  CONSTRAINT `fk_answer_question` FOREIGN KEY (`question_id`) REFERENCES `question` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_answer_user` FOREIGN KEY (`user_id`) REFERENCES `user` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='答题记录表';
