DROP TABLE IF EXISTS `question`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `question` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '题目ID',
  `knowledge_point_id` bigint NOT NULL COMMENT '所属知识点ID',
  `type` varchar(20) NOT NULL COMMENT '题型：SINGLE单选，MULTIPLE多选，JUDGE判断',
  `content` text NOT NULL COMMENT '题干',
  `answer` varchar(255) NOT NULL COMMENT '正确答案，如A、A,B、TRUE、FALSE',
  `analysis` text COMMENT '题目解析',
  `difficulty` tinyint NOT NULL DEFAULT '2' COMMENT '难度：1简单，2中等，3困难',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '状态：1启用，0禁用',
  `created_by` bigint DEFAULT NULL COMMENT '创建人用户ID',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_question_knowledge` (`knowledge_point_id`),
  KEY `idx_question_type` (`type`),
  KEY `idx_question_difficulty` (`difficulty`),
  KEY `idx_question_creator` (`created_by`),
  CONSTRAINT `fk_question_creator` FOREIGN KEY (`created_by`) REFERENCES `user` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_question_knowledge` FOREIGN KEY (`knowledge_point_id`) REFERENCES `knowledge_point` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=1039 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='题目表';
/*!40101 SET character_set_client = @saved_cs_client */;

LOCK TABLES `question` WRITE;
/*!40000 ALTER TABLE `question` DISABLE KEYS */;
INSERT INTO `question` VALUES (11,1,'SINGLE','在按字节编址的主存中，地址1000H与1001H所指向的存储单元关系是？','A','按字节编址时，每个地址对应一个字节。1000H与1001H相差1，因此它们是两个相邻的字节存储单元。',1,1,1,'2026-09-25 19:59:33','2026-09-25 19:59:33'),(12,1,'SINGLE','某计算机采用32位地址并按字节编址，其理论最大主存地址空间为多少？','D','32位地址可表示2^32个不同地址，按字节编址时每个地址对应1字节，所以地址空间为2^32字节，即4GB。',2,1,1,'2026-09-25 19:59:33','2026-09-25 19:59:33'),(13,1,'SINGLE','动态随机存取存储器DRAM需要周期性刷新的根本原因是？','B','DRAM用电容上的电荷表示信息，而电荷会随时间泄漏，因此必须周期性刷新。刷新与地址译码、读写速度或断电保存无关。',2,1,1,'2026-09-25 19:59:33','2026-09-25 19:59:33'),(14,1,'SINGLE','使用8K×8位存储芯片组成32K×16位存储器，至少需要多少片芯片？','C','容量方向需要32K÷8K=4组，字长方向需要16÷8=2片并联，每组2片，共4×2=8片。',3,1,1,'2026-09-25 19:59:33','2026-09-25 19:59:33'),(15,1,'MULTIPLE','下列哪些指标可用于描述主存储器的速度性能？','A,B,D','存取时间反映一次访问所需时间，存取周期反映连续两次访问的最小间隔，存储器带宽反映单位时间传输的数据量；存储容量描述可保存的数据规模，不是速度指标。',1,1,1,'2026-09-25 19:59:33','2026-09-25 19:59:33'),(16,1,'MULTIPLE','关于低位交叉编址的多模块存储器，下列说法正确的是？','A,C,D','低位交叉编址把连续地址分散到不同模块，允许多个模块重叠工作，从而提高连续访问带宽；它不改变所有模块容量之和，也不能保证任意访问都无冲突。',2,1,1,'2026-09-25 19:59:33','2026-09-25 19:59:33'),(17,1,'MULTIPLE','关于奇偶校验和海明校验，下列说法正确的是？','A,C,D','奇偶校验能发现奇数个位翻转，但一般不能定位和纠正错误；合理配置校验位的海明码可定位并纠正一位错误，其校验位数量与数据位数量有关。',3,1,1,'2026-09-25 19:59:33','2026-09-25 19:59:33'),(18,1,'JUDGE','只读存储器ROM在断电后通常仍能保持其中的信息。','TRUE','ROM属于非易失性存储器，断电后信息通常不会丢失，因此常用于保存固件或固定程序。',1,1,1,'2026-09-25 19:59:33','2026-09-25 19:59:33'),(19,1,'JUDGE','SRAM使用电容存储信息，因此必须像DRAM一样周期性刷新。','FALSE','SRAM通常由双稳态电路保存信息，只要持续供电就能保持状态，不需要DRAM式的周期刷新。',2,1,1,'2026-09-25 19:59:33','2026-09-25 19:59:33'),(20,1,'JUDGE','在四模块低位交叉存储器中，连续四个字地址可依次分布到四个不同模块。','TRUE','低位交叉使用地址低位选择模块，连续地址的低位依次变化，因此可轮流落到四个不同模块并实现并行交叉访问。',3,1,1,'2026-09-25 19:59:33','2026-09-25 19:59:33'),(21,2,'SINGLE','Cache命中率表示什么？','B','命中率是处理器访问的数据在Cache中找到的次数占总访问次数的比例，它反映Cache成功服务访存请求的概率。',1,1,1,'2026-09-25 19:59:33','2026-09-25 19:59:33'),(22,2,'SINGLE','某32位按字节编址系统采用直接映射Cache，块大小为64B，共有256个Cache行。地址中的标记字段应为多少位？','C','块内偏移需要log2(64)=6位，256行的行号需要log2(256)=8位，标记位数为32-6-8=18位。',2,1,1,'2026-09-25 19:59:33','2026-09-25 19:59:33'),(23,2,'SINGLE','采用写回法的Cache通常使用脏位，其作用是？','A','脏位记录Cache块是否已被处理器修改。被修改的块替换时才需要写回主存，未修改的块可直接丢弃。',2,1,1,'2026-09-25 19:59:33','2026-09-25 19:59:33'),(24,2,'SINGLE','某Cache命中时间为2ns，缺失率为5%，缺失代价为80ns。按“命中时间+缺失率×缺失代价”计算平均访问时间是多少？','B','平均访问时间=2ns+0.05×80ns=6ns。缺失代价是在完成命中判断后额外付出的时间。',3,1,1,'2026-09-25 19:59:33','2026-09-25 19:59:33'),(25,2,'MULTIPLE','关于Cache的基本特征，下列说法正确的是？','A,B,D','Cache利用程序访问的时间局部性和空间局部性，通常由高速SRAM构成，并由硬件自动管理；它提升访问速度，但不会扩大主存地址空间。',1,1,1,'2026-09-25 19:59:33','2026-09-25 19:59:33'),(26,2,'MULTIPLE','关于Cache地址映射方式，下列说法正确的是？','A,C,D','直接映射中主存块只能进入唯一Cache行；全相联映射允许进入任意行；组相联映射允许进入指定组内任意行，是两者的折中。',2,1,1,'2026-09-25 19:59:33','2026-09-25 19:59:33'),(27,2,'MULTIPLE','关于Cache替换策略，下列说法正确的是？','A,B,D','LRU倾向替换最长时间未使用的块，随机替换实现简单；直接映射中目标行唯一，无须在多个候选行间运行替换算法。FIFO只依据装入先后，不能保证替换最久未访问的数据。',3,1,1,'2026-09-25 19:59:33','2026-09-25 19:59:33'),(28,2,'JUDGE','Cache的容量通常远小于主存容量。','TRUE','Cache追求高速且成本较高，通常只保存主存中近期可能访问的一小部分数据，所以容量远小于主存。',1,1,1,'2026-09-25 19:59:33','2026-09-25 19:59:33'),(29,2,'JUDGE','采用写直达策略时，Cache写命中通常会同时更新主存。','TRUE','写直达策略在更新Cache副本的同时把数据写到下一级存储器，因此主存能及时保持一致。',2,1,1,'2026-09-25 19:59:33','2026-09-25 19:59:33'),(30,2,'JUDGE','增大Cache块大小一定能够降低缺失率。','FALSE','适当增大块可利用空间局部性，但块过大会减少Cache可容纳的块数并带来污染，还可能增加冲突和缺失代价，因此缺失率不一定持续下降。',3,1,1,'2026-09-25 19:59:33','2026-09-25 19:59:33'),(31,3,'SINGLE','一条机器指令中的操作码主要用于表示什么？','A','操作码指出处理器应执行的操作类型，如加法、访存或转移；操作数地址和寻址方式由指令中的其他字段描述。',1,1,1,'2026-09-25 19:59:33','2026-09-25 19:59:33'),(32,3,'SINGLE','立即寻址方式的操作数位于哪里？','C','立即寻址把操作数本身直接编码在指令中，无须根据地址再访问存储器读取该操作数。',2,1,1,'2026-09-25 19:59:33','2026-09-25 19:59:33'),(33,3,'SINGLE','相对寻址形成转移目标地址时，通常将形式地址或位移量加到哪个寄存器的内容上？','B','相对寻址以程序计数器PC为基准，将指令给出的有符号位移加到PC内容上形成目标地址，便于实现位置无关代码。',2,1,1,'2026-09-25 19:59:33','2026-09-25 19:59:33'),(34,3,'SINGLE','某32位定长三地址指令支持128种操作，每个寄存器字段需要表示32个寄存器。除操作码和三个寄存器字段外，剩余字段最多有多少位？','D','128种操作需要7位操作码，32个寄存器每个字段需要5位，三个寄存器字段共15位，因此剩余32-7-15=10位。',3,1,1,'2026-09-25 19:59:33','2026-09-25 19:59:33'),(35,3,'MULTIPLE','一条机器指令通常可以包含哪些信息？','A,B,C','指令需要说明执行什么操作、如何取得操作数以及操作数或其地址。处理器时钟频率属于硬件运行参数，不是每条指令的组成字段。',1,1,1,'2026-09-25 19:59:33','2026-09-25 19:59:33'),(36,3,'MULTIPLE','下列哪些通常属于RISC指令系统的设计特点？','A,C,D','RISC通常采用较规整的定长指令、较少且简单的寻址方式以及较多通用寄存器，便于流水线执行；大量复杂指令并依赖复杂微程序通常更接近CISC。',2,1,1,'2026-09-25 19:59:33','2026-09-25 19:59:33'),(37,3,'MULTIPLE','关于常见寻址方式，下列说法正确的是？','A,B,D','立即寻址直接在指令中给出操作数；间接寻址通常需要额外访问获得有效地址；变址寻址适合数组访问。寄存器寻址访问的是寄存器，不必先访问主存。',3,1,1,'2026-09-25 19:59:33','2026-09-25 19:59:33'),(38,3,'JUDGE','机器指令可以设计成零地址指令。','TRUE','栈式计算机可使用隐含的栈顶操作数，因此加法等指令可以不显式给出地址字段，形成零地址指令。',1,1,1,'2026-09-25 19:59:33','2026-09-25 19:59:33'),(39,3,'JUDGE','CISC指令功能较复杂，因此任意CISC程序都一定比RISC程序执行得更快。','FALSE','程序性能还受实现方式、流水线、编译器、存储层次和具体工作负载影响，不能仅凭指令复杂程度断定任意程序都更快。',2,1,1,'2026-09-25 19:59:33','2026-09-25 19:59:33'),(40,3,'JUDGE','完成一条顺序指令的取指后，程序计数器PC通常指向下一条将要取出的指令。','TRUE','顺序执行时，取指过程通常会按指令长度更新PC，使其保存下一条指令地址；转移指令随后可能再次改变PC。',3,1,1,'2026-09-25 19:59:33','2026-09-25 19:59:33'),(41,4,'SINGLE','处理器采用指令流水线的主要目的是什么？','C','流水线让多条指令的不同阶段重叠执行，主要提高单位时间完成的指令数，即吞吐率，而不是保证每条指令延迟都缩短。',1,1,1,'2026-09-25 19:59:33','2026-09-25 19:59:33'),(42,4,'SINGLE','一个理想五级流水线每级耗时2ns，忽略寄存器开销和停顿。第一条指令从进入流水线到完成需要多少时间？','D','第一条指令必须依次通过5级，每级2ns，所以延迟为5×2ns=10ns；流水线填满后才可能每2ns完成一条指令。',2,1,1,'2026-09-25 19:59:33','2026-09-25 19:59:33'),(43,4,'SINGLE','后续指令需要读取前一条尚未写回的运算结果，这属于哪类相关？','A','后续指令在前一条指令写入结果之前就试图读取该结果，属于写后读，即RAW数据相关。',2,1,1,'2026-09-25 19:59:33','2026-09-25 19:59:33'),(44,4,'SINGLE','理想情况下，100条指令在五级流水线中执行，每级耗时1个时钟周期。与非流水的五周期执行相比，加速比约为多少？','B','非流水执行时间为100×5=500周期；五级流水完成100条指令需要5+100-1=104周期，加速比为500÷104≈4.81。',3,1,1,'2026-09-25 19:59:33','2026-09-25 19:59:33'),(45,4,'MULTIPLE','指令流水线中常见的冒险类型包括哪些？','A,B,C','资源竞争产生结构冒险，指令间数据依赖产生数据冒险，分支或跳转改变取指方向产生控制冒险；“容量冒险”不是经典流水线冒险分类。',1,1,1,'2026-09-25 19:59:33','2026-09-25 19:59:33'),(46,4,'MULTIPLE','下列哪些措施有助于减小分支造成的流水线损失？','A,C,D','分支预测可提前选择取指方向，延迟分支利用原本可能空闲的位置，提前计算分支条件可更早确定目标；单纯降低Cache命中率只会增加停顿。',2,1,1,'2026-09-25 19:59:33','2026-09-25 19:59:33'),(47,4,'MULTIPLE','影响流水线实际加速效果的因素包括哪些？','A,C,D','各级耗时不均会受最慢级限制，流水寄存器会引入额外开销，各类冒险会产生停顿；增加级数并不保证加速比无限或必然增长。',3,1,1,'2026-09-25 19:59:33','2026-09-25 19:59:33'),(48,4,'JUDGE','采用流水线后，单条指令从开始到完成的延迟一定会缩短。','FALSE','流水线主要提高吞吐率，单条指令仍需经过全部阶段，而且流水寄存器还会增加开销，因此单条指令延迟不一定缩短。',1,1,1,'2026-09-25 19:59:33','2026-09-25 19:59:33'),(49,4,'JUDGE','数据转发可以消除所有类型的数据冒险停顿。','FALSE','数据转发能解决许多RAW相关，但某些情况如紧邻的加载后使用仍可能来不及取得数据，需要插入停顿；它也不能解决所有其他相关。',2,1,1,'2026-09-25 19:59:33','2026-09-25 19:59:33'),(50,4,'JUDGE','在各级耗时相同且没有停顿的理想情况下，当执行的指令数足够多时，k级流水线的加速比可趋近于k。','TRUE','非流水执行n条指令约需nk个阶段时间，理想k级流水约需k+n-1个阶段时间；当n很大时，nk/(k+n-1)趋近于k。',3,1,1,'2026-09-25 19:59:33','2026-09-25 19:59:33'),(76,8,'SINGLE','在长度为n的顺序表中按下标访问一个元素，其时间复杂度通常为？','A','顺序表使用连续存储空间，可由首地址和下标直接计算元素地址，因此随机访问时间复杂度为O(1)。',1,1,1,'2026-09-26 11:38:57','2026-09-26 11:38:57'),(77,8,'SINGLE','在不带头结点的单链表表头插入一个新结点，核心操作的时间复杂度为？','A','表头插入只需修改新结点和头指针，不随链表长度增长，因此为O(1)。',1,1,1,'2026-09-26 11:38:57','2026-09-26 11:38:57'),(78,9,'SINGLE','栈的插入和删除操作遵循的原则是？','B','栈只允许在栈顶进行插入和删除，遵循后进先出原则。',2,1,1,'2026-09-26 11:38:57','2026-09-26 11:38:57'),(79,9,'SINGLE','使用循环队列并约定牺牲一个存储单元时，队满条件通常是？','C','设数组长度为MaxSize，牺牲一个单元区分队空和队满时，队满条件为(rear+1)%MaxSize=front。',2,1,1,'2026-09-26 11:38:57','2026-09-26 11:38:57'),(80,10,'SINGLE','一棵含n个结点的非空树共有多少条边？','B','除根结点外，每个结点都恰有一条连接父结点的边，因此边数为n-1。',3,1,1,'2026-09-26 11:38:57','2026-09-26 11:38:57'),(81,10,'MULTIPLE','关于二叉树遍历，下列说法正确的有？','A,C,D','先序按根左右，中序按左根右，后序按左右根；层序遍历通常借助队列。',1,1,1,'2026-09-26 11:38:57','2026-09-26 11:38:57'),(82,11,'MULTIPLE','对图进行广度优先搜索时，通常需要使用哪些结构或标记？','A,B,D','BFS使用队列保存待扩展顶点，并用访问标记避免重复访问；图可用邻接表进行遍历。递归栈是深度优先搜索的典型实现手段。',2,1,1,'2026-09-26 11:38:57','2026-09-26 11:38:57'),(83,11,'MULTIPLE','关于图的基本概念，下列说法正确的有？','A,C,D','无向图所有顶点度数之和为边数的两倍；连通图任意两点间存在路径；生成树含全部顶点且有n-1条边。完全图不一定是有向图。',3,1,1,'2026-09-26 11:38:57','2026-09-26 11:38:57'),(84,12,'JUDGE','对有序顺序表进行二分查找时，每次比较都可以排除约一半的待查范围。','TRUE','二分查找根据中间元素与目标值的比较结果，将待查区间缩小到左半或右半，因此每次可排除约一半范围。',1,1,1,'2026-09-26 11:38:57','2026-09-26 11:46:10'),(85,12,'JUDGE','直接插入排序在任何输入情况下的时间复杂度都为O(n)。','FALSE','直接插入排序在序列已有序时可达到O(n)，但平均和最坏情况下需要移动、比较大量元素，时间复杂度为O(n²)。',2,1,1,'2026-09-26 11:38:57','2026-09-26 11:46:10'),(86,13,'SINGLE','同一进程中的多个线程通常共享的是？','C','同一进程内的线程共享进程地址空间和打开的文件等资源，但各自拥有栈和程序计数器。',1,1,1,'2026-09-26 11:38:57','2026-09-26 11:38:57'),(87,13,'SINGLE','一个运行中的进程因等待I/O完成而暂停执行时，通常转入什么状态？','B','进程等待I/O等事件时不能继续运行，会从运行态转入阻塞态。',1,1,1,'2026-09-26 11:38:57','2026-09-26 11:38:57'),(88,14,'SINGLE','在所有作业同时到达且运行时间已知的理想条件下，通常使平均周转时间较短的算法是？','A','短作业优先优先选择预计运行时间短的作业，在给定理想条件下能降低平均周转时间。',2,1,1,'2026-09-26 11:38:57','2026-09-26 11:38:57'),(89,14,'SINGLE','时间片轮转调度中，时间片设置得过小最可能导致什么结果？','D','时间片过小会频繁切换进程，使上下文切换开销占比增大。',2,1,1,'2026-09-26 11:38:57','2026-09-26 11:38:57'),(90,15,'SINGLE','用于保证同一时刻只有一个进程进入临界区的基本机制是？','B','互斥机制控制对临界资源的排他访问，从而保证临界区同一时刻最多由一个执行流进入。',3,1,1,'2026-09-26 11:38:57','2026-09-26 11:38:57'),(91,15,'MULTIPLE','关于进程状态转换，下列说法正确的有？','A,C,D','运行进程时间片用完可回到就绪态；阻塞进程等待事件发生后进入就绪态；就绪进程被调度后进入运行态。阻塞态不能未经事件完成直接运行。',1,1,1,'2026-09-26 11:38:57','2026-09-26 11:38:57'),(92,16,'MULTIPLE','关于分页存储管理，下列说法正确的有？','A,B,D','分页将逻辑空间分成页、物理空间分成页框，由页表完成映射；页大小通常由系统确定，并非每个进程随意选择。',2,1,1,'2026-09-26 11:38:57','2026-09-26 11:38:57'),(93,16,'MULTIPLE','关于虚拟内存，下列说法正确的有？','A,C,D','虚拟内存利用局部性，只装入当前需要的部分页面；缺页时由系统调入，页面置换算法影响性能。它不能让物理内存容量实际变大。',3,1,1,'2026-09-26 11:38:57','2026-09-26 11:38:57'),(94,17,'JUDGE','绝对路径从文件系统的根目录开始描述文件位置。','TRUE','绝对路径以根目录为起点，逐级给出到目标文件或目录的完整路径，因此不依赖当前工作目录。',1,1,1,'2026-09-26 11:38:57','2026-09-26 11:46:10'),(95,17,'JUDGE','文件的物理结构只能采用连续分配方式。','FALSE','文件可采用连续分配、链接分配或索引分配等物理结构，不同方式在随机访问、空间利用率和扩展能力上各有特点。',2,1,1,'2026-09-26 11:38:57','2026-09-26 11:46:10'),(96,18,'SINGLE','OSI参考模型中，为端系统进程提供端到端通信服务的是哪一层？','C','传输层面向端系统进程提供端到端服务，网络层主要负责主机间的分组转发。',1,1,1,'2026-09-26 11:38:57','2026-09-26 11:38:57'),(97,18,'SINGLE','在分层网络体系中，同一层实体之间通信所遵循的规则集合称为？','B','协议规定对等实体通信时的数据格式、语义和同步规则。',1,1,1,'2026-09-26 11:38:57','2026-09-26 11:38:57'),(98,19,'SINGLE','数据链路层传输的数据单元通常称为？','B','数据链路层把网络层分组封装成帧，并在相邻结点间传输。',2,1,1,'2026-09-26 11:38:57','2026-09-26 11:38:57'),(99,19,'SINGLE','以太网交换机学习转发表时主要依据收到帧的什么信息？','A','交换机根据入端口和帧的源MAC地址学习主机位置，再依据目的MAC地址转发。',2,1,1,'2026-09-26 11:38:57','2026-09-26 11:38:57'),(100,20,'SINGLE','路由器转发IP分组时主要依据的是？','D','路由器查看目的IP地址并与路由表前缀匹配，选择下一跳和输出接口。',3,1,1,'2026-09-26 11:38:57','2026-09-26 11:38:57'),(101,20,'MULTIPLE','关于网络分层与封装，下列说法正确的有？','A,B,D','上层数据逐层封装控制信息；接收端逐层解封装；分层便于模块化设计。协议描述对等层规则，服务描述下层向上层提供的能力。',1,1,1,'2026-09-26 11:38:57','2026-09-26 11:38:57'),(102,21,'MULTIPLE','关于TCP和UDP，下列说法正确的有？','A,C,D','TCP面向连接并提供可靠字节流；UDP无连接且首部开销较小；二者均使用端口号区分应用进程。',2,1,1,'2026-09-26 11:38:57','2026-09-26 11:38:57'),(103,21,'MULTIPLE','关于可靠传输机制，下列说法正确的有？','A,B,C','序号用于排序和识别重复，确认反映接收情况，超时重传处理可能的丢失；校验和主要检测差错，不能保证所有错误都自动修复。',3,1,1,'2026-09-26 11:38:57','2026-09-26 11:38:57'),(104,22,'JUDGE','DNS可以将域名解析为对应的IP地址。','TRUE','DNS是应用层的域名系统，可通过分布式查询把便于记忆的域名解析为主机使用的IP地址。',1,1,1,'2026-09-26 11:38:57','2026-09-26 11:46:10'),(105,22,'JUDGE','HTTP协议本身通常被设计为无状态协议。','TRUE','HTTP请求彼此独立，协议本身不自动保存会话状态；实际应用可借助Cookie等机制维持状态。',2,1,1,'2026-09-26 11:38:57','2026-09-26 11:38:57'),(107,23,'SINGLE','极限 lim(x→0) sin x / x 的值为？','B','这是重要极限之一，x以弧度度量时lim(x→0)sin x/x=1。',1,1,1,'2026-09-26 11:38:57','2026-09-26 11:38:57'),(108,23,'SINGLE','函数f(x)在x=a处连续的充分必要条件是？','D','连续要求函数在该点有定义、极限存在，并且极限等于函数值。',1,1,1,'2026-09-26 11:38:57','2026-09-26 11:38:57'),(109,24,'SINGLE','函数e^(2x)的导数是？','C','由复合函数求导法则，d(e^(2x))/dx=2e^(2x)。',2,1,1,'2026-09-26 11:38:57','2026-09-26 11:38:57'),(110,24,'SINGLE','若f\'(x)>0在某区间恒成立，则f(x)在该区间通常具有何种性质？','A','导数恒正表示函数随x增加而严格增加。',2,1,1,'2026-09-26 11:38:57','2026-09-26 11:38:57'),(111,25,'SINGLE','定积分 ∫[0,1] 2x dx 的值为？','B','2x的一个原函数为x²，代入上下限得到1²-0²=1。',3,1,1,'2026-09-26 11:38:57','2026-09-26 11:38:57'),(112,25,'MULTIPLE','关于定积分，下列说法正确的有？','A,B,D','定积分具有线性性和区间可加性；连续函数在闭区间可积。定积分值是数，不是自变量的函数。',1,1,1,'2026-09-26 11:38:57','2026-09-26 11:38:57'),(113,26,'MULTIPLE','关于二元函数偏导数和全微分，下列说法正确的有？','A,C,D','偏导固定其他变量；可微可推出连续且偏导存在。仅偏导存在一般不能推出可微。',2,1,1,'2026-09-26 11:38:57','2026-09-26 11:38:57'),(114,26,'MULTIPLE','关于极值判定，下列说法正确的有？','A,B,C','可导内点极值通常满足一阶偏导为零；二阶导数可用于充分条件判定；边界极值需另行考察。驻点不一定都是极值点。',3,1,1,'2026-09-26 11:38:57','2026-09-26 11:38:57'),(115,27,'JUDGE','微分方程y″=2y的通解可以写成y=Ce^(2x)。','FALSE','将y=Ce^(2x)代入可得y″=4Ce^(2x)=4y，并不满足y″=2y；原方程的特征根为±√2。',1,1,1,'2026-09-26 11:38:57','2026-09-26 11:47:28'),(116,27,'JUDGE','微分方程y\'=f(x)的通解可写为f(x)的一个原函数加任意常数。','TRUE','对等式两边关于x积分，得到y=∫f(x)dx+C。',2,1,1,'2026-09-26 11:38:57','2026-09-26 11:38:57'),(117,28,'SINGLE','上三角矩阵的行列式等于什么？','C','三角矩阵的行列式等于主对角线元素的乘积。',1,1,1,'2026-09-26 11:38:57','2026-09-26 11:38:57'),(118,28,'SINGLE','交换行列式的两行后，行列式的值如何变化？','B','行列式交换任意两行会变号。',1,1,1,'2026-09-26 11:38:57','2026-09-26 11:38:57'),(119,29,'SINGLE','n阶方阵A可逆的一个等价条件是？','D','A可逆等价于det(A)≠0，也等价于秩为n。',2,1,1,'2026-09-26 11:38:57','2026-09-26 11:38:57'),(120,29,'SINGLE','矩阵乘法AB有定义的条件是？','A','A的列数必须等于B的行数，结果矩阵行数取A、列数取B。',2,1,1,'2026-09-26 11:38:57','2026-09-26 11:38:57'),(121,30,'SINGLE','向量组线性相关意味着什么？','B','线性相关表示存在一组不全为零的系数，使向量线性组合等于零向量。',3,1,1,'2026-09-26 11:38:57','2026-09-26 11:38:57'),(122,30,'MULTIPLE','关于向量组线性相关性，下列说法正确的有？','A,C,D','含零向量的向量组相关；一个向量能由其余向量线性表示时相关；无关组的每个子组仍无关。相关组的任意子组未必相关。',1,1,1,'2026-09-26 11:38:57','2026-09-26 11:38:57'),(123,31,'MULTIPLE','关于齐次线性方程组Ax=0，下列说法正确的有？','A,B,D','齐次方程组必有零解；rank(A)<未知量个数时存在非零解；解集对加法和数乘封闭。它不一定只有唯一解。',2,1,1,'2026-09-26 11:38:57','2026-09-26 11:38:57'),(124,31,'MULTIPLE','关于非齐次线性方程组Ax=b，下列说法正确的有？','A,C,D','有解条件是系数矩阵与增广矩阵秩相等；若秩等于未知量个数则解唯一，若小于未知量个数则有无穷多解。',3,1,1,'2026-09-26 11:38:57','2026-09-26 11:38:57'),(125,32,'JUDGE','属于不同特征值的特征向量线性无关。','TRUE','线性代数基本定理表明，不同特征值对应的非零特征向量构成线性无关组。',1,1,1,'2026-09-26 11:38:57','2026-09-26 11:38:57'),(126,32,'JUDGE','任意实对称矩阵都可以通过正交变换对角化。','TRUE','实对称矩阵具有一组标准正交特征向量，因此可被正交矩阵相似对角化。',2,1,1,'2026-09-26 11:38:57','2026-09-26 11:38:57'),(138,33,'SINGLE','Choose the best word: The committee decided to ___ more funds to rural schools.','B','Allocate means to distribute resources for a particular purpose, which fits the context of assigning funds.',1,1,1,'2026-09-26 11:38:57','2026-09-26 11:38:57'),(139,33,'SINGLE','Choose the closest meaning of “significant” in “a significant improvement”.','C','In this context, significant means important or large enough to be noticed.',1,1,1,'2026-09-26 11:38:57','2026-09-26 11:38:57'),(140,33,'SINGLE','Choose the best word: Regular exercise can ___ the risk of heart disease.','A','Reduce collocates naturally with risk and means make it smaller.',2,1,1,'2026-09-26 11:38:57','2026-09-26 11:38:57'),(141,34,'SINGLE','Choose the correct sentence.','D','Neither as the subject is singular here, so the verb should be has; the past participle completed follows has.',2,1,1,'2026-09-26 11:38:57','2026-09-26 11:38:57'),(142,34,'SINGLE','If she ___ more time, she would join the volunteer program.','B','The sentence describes an unreal present condition, so the if-clause uses the simple past: had.',3,1,1,'2026-09-26 11:38:57','2026-09-26 11:38:57'),(143,34,'MULTIPLE','Which sentences are grammatically correct?','A,C,D','A uses present perfect correctly, C has subject-verb agreement, and D uses a correct participle clause. B should be “suggested that he take” or “suggested taking.”',1,1,1,'2026-09-26 11:38:57','2026-09-26 11:38:57'),(144,35,'MULTIPLE','Which expressions are standard English collocations?','A,B,D','Take responsibility, have an impact on, and be aware of are standard collocations. The natural expression is pay attention to, not make attention to.',2,1,1,'2026-09-26 11:38:57','2026-09-26 11:38:57'),(145,35,'MULTIPLE','Which words can replace “important” in a formal context without reversing the meaning?','A,C,D','Crucial, essential and significant all express importance; trivial means unimportant.',3,1,1,'2026-09-26 11:38:57','2026-09-26 11:38:57'),(146,36,'JUDGE','“Therefore” is commonly used to introduce a result or conclusion. ','TRUE','Therefore signals that the following statement is a consequence or conclusion based on what came before.',1,1,1,'2026-09-26 11:38:57','2026-09-26 11:38:57'),(147,36,'JUDGE','“Economic” and “economical” can always replace each other without changing meaning.','FALSE','Economic usually relates to the economy, while economical means avoiding waste or being cost-effective; they are not generally interchangeable.',2,1,1,'2026-09-26 11:38:57','2026-09-26 11:38:57'),(148,37,'SINGLE','Read: “Many cities are planting trees along busy roads. The trees lower summer temperatures, absorb some pollutants and make walking more pleasant.” What is the main idea?','B','All details support the central idea that roadside trees bring several benefits to cities.',1,1,1,'2026-09-26 11:38:57','2026-09-26 11:38:57'),(149,37,'SINGLE','Read: “Remote work saves commuting time, but it can also blur the boundary between work and rest. Successful arrangements therefore require clear routines.” Which title is best?','C','The passage presents both a benefit and a challenge, then recommends clear routines for balance.',1,1,1,'2026-09-26 11:38:57','2026-09-26 11:38:57'),(150,37,'SINGLE','Read: “Small libraries increasingly lend tools, host workshops and provide internet access in addition to books.” What does the sentence mainly show?','A','The sentence emphasizes that libraries are expanding their community services beyond lending books.',2,1,1,'2026-09-26 11:38:57','2026-09-26 11:38:57'),(151,38,'SINGLE','Read: “The museum is free on Fridays after 5 p.m., but advance booking is still required.” Which statement is correct?','D','The text explicitly states both the free period and the continuing booking requirement.',2,1,1,'2026-09-26 11:38:57','2026-09-26 11:38:57'),(152,38,'SINGLE','Read: “Researchers surveyed 600 commuters; 62 percent said reliability mattered more than ticket price.” What did most respondents value more?','B','The stated majority, 62 percent, selected reliability over ticket price.',3,1,1,'2026-09-26 11:38:57','2026-09-26 11:38:57'),(153,38,'MULTIPLE','Which practices help answer detail questions accurately?','A,C,D','Locating keywords, checking nearby context and matching paraphrases help verify details. Choosing an option only because it repeats one word can be misleading.',1,1,1,'2026-09-26 11:38:57','2026-09-26 11:38:57'),(154,39,'MULTIPLE','Read: “Lena brought an umbrella although the sky was clear when she left. By noon, dark clouds had gathered.” Which inferences are reasonable?','A,B,D','The umbrella suggests Lena anticipated rain; changing clouds increase the chance it would be useful. The text does not say she dislikes sunshine.',2,1,1,'2026-09-26 11:38:57','2026-09-26 11:38:57'),(155,39,'MULTIPLE','Which statements describe sound reading inference?','A,C,D','A sound inference is supported by textual evidence, respects the author\'s tone and avoids claims stronger than the evidence. Personal preference alone is insufficient.',3,1,1,'2026-09-26 11:38:57','2026-09-26 11:38:57'),(156,40,'JUDGE','The first dictionary meaning of a word is always the correct meaning in every passage.','FALSE','Words often have multiple meanings, so readers must use grammatical and contextual clues to choose the appropriate sense.',1,1,1,'2026-09-26 11:38:57','2026-09-26 11:38:57'),(157,40,'JUDGE','Headings and topic sentences can help readers recognize a passage\'s structure.','TRUE','They often signal the subject and relationship of sections, helping readers follow the organization.',2,1,1,'2026-09-26 11:38:57','2026-09-26 11:38:57'),(158,41,'SINGLE','In “The plan proposed by the research team has attracted public attention,” what is the main predicate?','C','The subject is The plan, proposed by the research team is a modifier, and has attracted is the main predicate.',1,1,1,'2026-09-26 11:38:57','2026-09-26 11:38:57'),(159,41,'SINGLE','Which is the main clause of “Although costs rose, the company continued the project because demand remained strong”?','B','Although costs rose and because demand remained strong are subordinate clauses; the main clause is the company continued the project.',1,1,1,'2026-09-26 11:38:57','2026-09-26 11:38:57'),(160,41,'SINGLE','The best first step when translating a long English sentence is usually to identify what?','A','Finding the subject, main predicate and object establishes the sentence backbone before modifiers are processed.',2,1,1,'2026-09-26 11:38:57','2026-09-26 11:38:57'),(161,42,'SINGLE','In “Students who manage their time well often feel less stressed,” the clause beginning with “who” modifies which word?','D','The relative clause who manage their time well modifies Students.',2,1,1,'2026-09-26 11:38:57','2026-09-26 11:38:57'),(162,42,'SINGLE','Which Chinese rendering best preserves the emphasis of “Only by cooperation can the problem be solved”?','B','Only by introduces the necessary means; the natural Chinese rendering emphasizes that cooperation is required to solve the problem.',3,1,1,'2026-09-26 11:38:57','2026-09-26 11:38:57'),(163,42,'MULTIPLE','Which statements about clause translation are appropriate?','A,C,D','Translators should identify logical relations, determine what a relative clause modifies, and may adjust clause order for natural Chinese. Mechanical word-for-word order is not always suitable.',1,1,1,'2026-09-26 11:38:57','2026-09-26 11:38:57'),(164,43,'MULTIPLE','Which translations of common expressions are appropriate?','A,B,C','Play a vital role in, be exposed to and take ... into account have the listed established meanings. By accident means 偶然地, not 故意地.',2,1,1,'2026-09-26 11:38:57','2026-09-26 11:38:57'),(165,43,'MULTIPLE','Which principles improve translation accuracy?','A,C,D','Meaning should be determined from context, terminology kept consistent, and pronoun references clarified. Copying the first dictionary meaning without context is unreliable.',3,1,1,'2026-09-26 11:38:57','2026-09-26 11:38:57'),(166,44,'JUDGE','An English passive sentence must always be translated into a Chinese passive sentence.','FALSE','Chinese often prefers an active or subjectless expression when it is clearer and more natural, so voice can be adjusted while preserving meaning.',1,1,1,'2026-09-26 11:38:57','2026-09-26 11:38:57'),(167,44,'JUDGE','Identifying the sentence backbone before handling modifiers is useful for translating long sentences.','TRUE','The backbone fixes the central proposition, after which modifiers and clauses can be attached or reordered accurately.',2,1,1,'2026-09-26 11:38:57','2026-09-26 11:38:57'),(168,45,'SINGLE','Which opening is most suitable for a formal application email?','C','I am writing to apply for... states the purpose directly and uses an appropriate formal tone.',1,1,1,'2026-09-26 11:38:57','2026-09-26 11:38:57'),(169,45,'SINGLE','Which closing is most appropriate for a polite request email?','B','The sentence expresses appreciation and invites a response in a courteous, conventional way.',1,1,1,'2026-09-26 11:38:57','2026-09-26 11:38:57'),(170,45,'SINGLE','A notice should usually make which information clear?','D','A useful notice clearly states the event, time, place and relevant participation instructions.',2,1,1,'2026-09-26 11:38:57','2026-09-26 11:38:57'),(171,46,'SINGLE','Which sentence appropriately introduces a chart?','A','The sentence objectively identifies what the chart presents before analysis begins.',2,1,1,'2026-09-26 11:38:57','2026-09-26 11:38:57'),(172,46,'SINGLE','If a value rises from 20 to 40, which description is accurate?','C','The value doubles and increases by 100 percent; it does not merely rise by 20 percent.',3,1,1,'2026-09-26 11:38:57','2026-09-26 11:38:57'),(173,46,'MULTIPLE','Which elements belong in a clear chart essay?','A,B,D','A chart essay normally gives an overview, selects key comparisons and offers a reasonable interpretation. Listing every number without organization reduces clarity.',1,1,1,'2026-09-26 11:38:57','2026-09-26 11:38:57'),(174,47,'MULTIPLE','Which sentences are suitable for formal academic writing?','A,C,D','These sentences use clear grammar and formal tone. “A lot of stuffs” is ungrammatical because stuff is uncountable and the expression is informal.',2,1,1,'2026-09-26 11:38:57','2026-09-26 11:38:57'),(175,47,'MULTIPLE','Which editing actions improve language accuracy?','A,B,C','Checking agreement, tense consistency and collocations catches common errors. Replacing every simple word with a rare one can reduce accuracy and clarity.',3,1,1,'2026-09-26 11:38:57','2026-09-26 11:38:57'),(176,48,'JUDGE','Contractions such as “can\'t” and “won\'t” are mandatory in every formal essay.','FALSE','Formal writing often prefers full forms, and contractions are never mandatory; register should match the task.',1,1,1,'2026-09-26 11:38:57','2026-09-26 11:38:57'),(177,48,'JUDGE','A well-developed paragraph should normally focus on one controlling idea.','TRUE','Paragraph unity comes from a clear topic idea supported by relevant explanations and examples.',2,1,1,'2026-09-26 11:38:57','2026-09-26 11:38:57'),(201,49,'SINGLE','哲学基本问题是下列哪一对关系问题？','A','哲学基本问题是思维和存在、意识和物质的关系问题，包括何者为第一性以及能否被认识。',1,1,1,'2026-09-26 11:39:03','2026-09-26 11:39:03'),(202,49,'SINGLE','辩证唯物主义认为，世界的统一性在于什么？','C','世界统一于物质，物质世界是多样性的统一。',1,1,1,'2026-09-26 11:39:03','2026-09-26 11:39:03'),(203,50,'SINGLE','唯物辩证法的实质和核心是？','B','对立统一规律揭示事物发展的根本动力，是唯物辩证法的实质和核心。',2,1,1,'2026-09-26 11:39:03','2026-09-26 11:39:03'),(204,50,'SINGLE','区分量变和质变的根本标志是？','D','变化是否超出事物保持其质的度，是区分量变和质变的根本标志。',2,1,1,'2026-09-26 11:39:03','2026-09-26 11:39:03'),(205,51,'SINGLE','马克思主义认识论认为，认识的来源是？','A','实践是认识的来源、动力、目的，也是检验真理的唯一标准。',3,1,1,'2026-09-26 11:39:03','2026-09-26 11:39:03'),(206,51,'MULTIPLE','关于实践和认识的关系，下列说法正确的有？','A,B,D','实践产生认识需要、提供手段并检验认识真理性；正确认识也能指导实践。认识不能脱离实践自行完成全部发展。',1,1,1,'2026-09-26 11:39:03','2026-09-26 11:39:03'),(207,52,'MULTIPLE','关于社会存在和社会意识，下列说法正确的有？','A,C,D','社会存在决定社会意识，社会意识具有相对独立性并能反作用于社会存在；二者并非机械同步。',2,1,1,'2026-09-26 11:39:03','2026-09-26 11:39:03'),(208,52,'MULTIPLE','关于人民群众的历史作用，下列说法正确的有？','A,B,C','人民群众是社会物质财富、精神财富的创造者，也是社会变革的决定力量；历史并非由少数英雄任意创造。',3,1,1,'2026-09-26 11:39:03','2026-09-26 11:39:03'),(209,53,'JUDGE','商品的价值量由生产该商品的社会必要劳动时间决定。','TRUE','商品价值量取决于生产商品所耗费的社会必要劳动时间，而不是某个生产者实际耗费的个别劳动时间。',1,1,1,'2026-09-26 11:39:03','2026-09-26 11:46:10'),(210,53,'JUDGE','剩余价值是在商品流通中通过等价交换直接产生的。','FALSE','等价交换本身不产生剩余价值；剩余价值来源于雇佣工人在生产过程中创造的超过劳动力价值的价值。',2,1,1,'2026-09-26 11:39:03','2026-09-26 11:39:03'),(211,54,'SINGLE','毛泽东思想活的灵魂不包括下列哪一项？','D','实事求是、群众路线、独立自主是毛泽东思想活的灵魂；闭关自守不属于其中内容。',1,1,1,'2026-09-26 11:39:03','2026-09-26 11:39:03'),(212,54,'SINGLE','毛泽东思想初步形成的重要标志是提出了什么理论？','B','农村包围城市、武装夺取政权道路理论的提出，标志着毛泽东思想初步形成。',1,1,1,'2026-09-26 11:39:03','2026-09-26 11:39:03'),(213,55,'SINGLE','新民主主义革命的领导力量是？','C','无产阶级通过中国共产党实现对新民主主义革命的领导。',2,1,1,'2026-09-26 11:39:03','2026-09-26 11:39:03'),(214,55,'SINGLE','中国革命走农村包围城市道路的根本在于处理好哪三者关系？','A','这条道路要求把土地革命、武装斗争和农村革命根据地建设结合起来。',2,1,1,'2026-09-26 11:39:03','2026-09-26 11:39:03'),(215,56,'SINGLE','我国对资本主义工商业进行社会主义改造所采取的创造性道路是？','D','党对资本主义工商业采取和平赎买方针，实现了马克思列宁主义相关设想的中国化实践。',3,1,1,'2026-09-26 11:39:03','2026-09-26 11:39:03'),(216,56,'MULTIPLE','毛泽东思想活的灵魂包括哪些方面？','A,B,C','实事求是、群众路线、独立自主构成毛泽东思想活的灵魂。教条主义与其精神相违背。',1,1,1,'2026-09-26 11:39:03','2026-09-26 11:39:03'),(217,57,'MULTIPLE','社会主义建设道路初步探索取得的成果包括哪些？','A,C,D','探索形成了调动一切积极因素、正确处理人民内部矛盾、走中国工业化道路等重要思想。照搬外国模式不是其正确成果。',2,1,1,'2026-09-26 11:39:03','2026-09-26 11:39:03'),(218,57,'MULTIPLE','关于社会主义社会矛盾，下列说法正确的有？','A,B,D','社会主义社会仍有矛盾；基本矛盾可通过社会主义制度自身调整完善来解决；敌我矛盾与人民内部矛盾性质不同。',3,1,1,'2026-09-26 11:39:03','2026-09-26 11:39:03'),(219,58,'JUDGE','邓小平理论回答了什么是社会主义、怎样建设社会主义这一基本问题。','TRUE','邓小平理论围绕什么是社会主义、怎样建设社会主义这一基本问题，形成了一系列相互联系的基本观点。',1,1,1,'2026-09-26 11:39:03','2026-09-26 11:46:10'),(220,58,'JUDGE','毛泽东思想属于中国特色社会主义理论体系的组成部分。','FALSE','毛泽东思想和中国特色社会主义理论体系都是马克思主义中国化时代化成果，但教材体系中二者是相互衔接的两大理论成果，并非前者属于后者。',2,1,1,'2026-09-26 11:39:03','2026-09-26 11:39:03'),(221,59,'SINGLE','中国特色社会主义进入新时代，我国社会主要矛盾转化为什么？','B','主要矛盾已转化为人民日益增长的美好生活需要和不平衡不充分的发展之间的矛盾。',1,1,1,'2026-09-26 11:39:03','2026-09-26 11:39:03'),(222,59,'SINGLE','新时代我国发展所处的历史阶段判断是？','C','我国仍处于并将长期处于社会主义初级阶段的基本国情没有变。',1,1,1,'2026-09-26 11:39:03','2026-09-26 11:39:03'),(223,60,'SINGLE','中国式现代化的本质要求不包括下列哪项？','D','中国式现代化坚持中国共产党领导和中国特色社会主义，追求共同富裕与和平发展，不以对外扩张为目标。',2,1,1,'2026-09-26 11:39:03','2026-09-26 11:39:03'),(224,60,'SINGLE','中国式现代化区别于西方现代化的重要特征之一是？','A','全体人民共同富裕是中国式现代化的中国特色和重要目标。',2,1,1,'2026-09-26 11:39:03','2026-09-26 11:39:03'),(225,61,'SINGLE','全面深化改革的总目标是？','C','总目标是完善和发展中国特色社会主义制度，推进国家治理体系和治理能力现代化。',3,1,1,'2026-09-26 11:39:03','2026-09-26 11:39:03'),(226,61,'MULTIPLE','中国式现代化具有哪些中国特色？','A,B,C,D','人口规模巨大、共同富裕、物质文明和精神文明协调、人与自然和谐共生、和平发展等都是其中国特色。',1,1,1,'2026-09-26 11:39:03','2026-09-26 11:39:03'),(227,62,'MULTIPLE','全面依法治国要求坚持哪些方面的共同推进？','A,C,D','依法治国、依法执政、依法行政共同推进，法治国家、法治政府、法治社会一体建设。以言代法违背法治原则。',2,1,1,'2026-09-26 11:39:03','2026-09-26 11:39:03'),(228,62,'MULTIPLE','关于法治建设，下列说法正确的有？','A,B,D','党的领导、人民当家作主、依法治国有机统一；宪法具有最高法律地位；公平正义是法治价值追求。法治不排斥道德作用。',3,1,1,'2026-09-26 11:39:03','2026-09-26 11:39:03'),(229,63,'JUDGE','创新、协调、绿色、开放、共享构成新发展理念的主要内容。','TRUE','新发展理念是一个系统的理论体系，明确回答发展动力、发展平衡、人与自然、内外联动和社会公平等问题。',1,1,1,'2026-09-26 11:39:03','2026-09-26 11:46:10'),(230,63,'JUDGE','高质量发展只要求提高经济增长速度，不需要关注结构、效益和可持续性。','FALSE','高质量发展强调质量变革、效率变革、动力变革，需要统筹结构、效益、公平和可持续性，不能只看增长速度。',2,1,1,'2026-09-26 11:39:03','2026-09-26 11:46:10'),(231,64,'SINGLE','近代中国最基本的国情是？','A','鸦片战争后，中国逐步沦为半殖民地半封建社会，这是认识近代中国问题的基本依据。',1,1,1,'2026-09-26 11:39:03','2026-09-26 11:39:03'),(232,64,'SINGLE','近代中国社会各种矛盾中最主要的矛盾是？','C','帝国主义和中华民族的矛盾是各种矛盾中最主要的矛盾，封建主义和人民大众的矛盾也是主要矛盾。',1,1,1,'2026-09-26 11:39:03','2026-09-26 11:39:03'),(233,65,'SINGLE','洋务运动前期提出的口号是？','B','洋务派前期以“自强”为口号兴办军事工业，后期以“求富”为口号兴办民用企业。',2,1,1,'2026-09-26 11:39:03','2026-09-26 11:39:03'),(234,65,'SINGLE','戊戌维新运动的性质是？','D','戊戌维新是资产阶级性质的改良运动，也是一场爱国救亡运动和思想启蒙运动。',2,1,1,'2026-09-26 11:39:03','2026-09-26 11:39:03'),(235,66,'SINGLE','辛亥革命最突出的历史功绩是？','A','辛亥革命推翻清王朝统治，结束了延续两千多年的君主专制制度，建立共和政体。',3,1,1,'2026-09-26 11:39:03','2026-09-26 11:39:03'),(236,66,'MULTIPLE','近代中国人民对国家出路的早期探索包括哪些？','A,B,D','太平天国运动、洋务运动和戊戌维新都是早期探索；社会主义改造发生在新中国成立后。',1,1,1,'2026-09-26 11:39:03','2026-09-26 11:39:03'),(237,67,'MULTIPLE','中国共产党成立的历史条件包括哪些？','A,C,D','马克思主义传播、工人阶级成长以及马克思主义同工人运动结合，为建党提供条件。君主专制加强不是建党条件。',2,1,1,'2026-09-26 11:39:03','2026-09-26 11:39:03'),(238,67,'MULTIPLE','中国共产党成立的历史意义包括哪些？','A,B,C','中国共产党的成立使中国革命有了坚强领导核心、科学指导思想和新的革命方法，中国革命面貌焕然一新。它没有在成立当日立即完成全部任务。',3,1,1,'2026-09-26 11:39:03','2026-09-26 11:39:03'),(239,68,'JUDGE','辛亥革命彻底改变了中国半殖民地半封建社会的性质。','FALSE','辛亥革命结束了君主专制制度，但没有完成反帝反封建任务，中国社会性质没有得到根本改变。',1,1,1,'2026-09-26 11:39:03','2026-09-26 11:39:03'),(240,68,'JUDGE','中华人民共和国成立标志着中国人民从此站起来了。','TRUE','新中国成立结束了少数剥削者统治广大劳动人民的历史，实现了民族独立和人民解放的重要历史转折。',2,1,1,'2026-09-26 11:39:03','2026-09-26 11:39:03'),(241,69,'SINGLE','人生观的核心是？','B','人生目的是人生观的核心，它回答人为什么活着并制约人生态度和人生价值选择。',1,1,1,'2026-09-26 11:39:03','2026-09-26 11:39:03'),(242,69,'SINGLE','评价人生价值的根本尺度是？','D','根本尺度在于一个人的实践活动是否符合社会发展的客观规律、是否促进历史进步。',1,1,1,'2026-09-26 11:39:03','2026-09-26 11:39:03'),(243,70,'SINGLE','理想与现实的关系是？','A','理想源于现实又超越现实，并可在一定条件下通过实践转化为现实。',2,1,1,'2026-09-26 11:39:03','2026-09-26 11:39:03'),(244,70,'SINGLE','实现理想的根本途径是？','C','艰苦奋斗、勇于实践是把理想转化为现实的根本途径。',2,1,1,'2026-09-26 11:39:03','2026-09-26 11:39:03'),(245,71,'SINGLE','新时代爱国主义的本质是？','B','当代中国，爱国主义的本质是坚持爱国和爱党、爱社会主义高度统一。',3,1,1,'2026-09-26 11:39:03','2026-09-26 11:39:03'),(246,71,'MULTIPLE','树立正确人生观需要反对哪些错误倾向？','A,C,D','拜金主义、享乐主义和极端个人主义把金钱、享乐或个人私利绝对化，应当反对。服务人民、奉献社会是正确价值追求。',1,1,1,'2026-09-26 11:39:03','2026-09-26 11:39:03'),(247,72,'MULTIPLE','社会主义核心价值观国家层面的价值目标包括哪些？','A,B,C,D','富强、民主、文明、和谐共同构成国家层面的价值目标。',2,1,1,'2026-09-26 11:39:03','2026-09-26 11:39:03'),(248,72,'MULTIPLE','关于公民权利和义务，下列说法正确的有？','A,C,D','权利与义务相统一；行使权利有法律边界；履行义务是公民责任。公民不能只享权利而拒绝义务。',3,1,1,'2026-09-26 11:39:03','2026-09-26 11:39:03'),(249,73,'JUDGE','宪法是国家的根本法，具有最高的法律效力。','TRUE','宪法规定国家根本制度和根本任务，是其他法律制定的依据，任何法律法规都不得同宪法相抵触。',1,1,1,'2026-09-26 11:39:03','2026-09-26 11:46:10'),(250,73,'JUDGE','法律面前人人平等意味着任何人在所有情况下都必须得到完全相同的结果。','FALSE','平等强调法律地位、适用和保护上的平等，并不否认依法根据事实、责任和具体条件作出不同处理。',2,1,1,'2026-09-26 11:39:03','2026-09-26 11:39:03'),(251,72,'SINGLE','社会主义核心价值观最后一句','A','自由平等公正法治',1,0,1,'2026-09-27 15:32:46','2026-09-27 15:32:46'),(252,8,'SINGLE','在不考虑扩容的前提下，下列哪种线性表存储结构通常支持按下标在O(1)时间内访问元素？','A','顺序表中的元素连续存放，可由首地址、元素大小和下标直接计算目标地址，因此按下标访问通常为O(1)；链表需要沿指针逐结点查找。',1,1,1,'2026-10-08 17:23:56','2026-10-08 17:23:56'),(253,8,'SINGLE','长度为n的顺序表已有足够容量，在表头插入一个元素时需要移动的原有元素个数为多少？','D','为了给新表头元素腾出位置，原有n个元素都要向后移动一个位置，因此需要移动n个原有元素。',2,1,1,'2026-10-08 17:23:56','2026-10-08 17:23:56'),(254,8,'SINGLE','在单链表中，若只给出头指针和某结点p，要寻找p的直接前驱，最坏时间复杂度为多少？','C','单链表结点只保存后继指针，无法由p直接反向找到前驱，只能从头结点开始顺序查找，最坏需要遍历O(n)个结点。',2,1,1,'2026-10-08 17:23:56','2026-10-08 17:23:56'),(255,8,'MULTIPLE','与顺序表相比，链式存储线性表通常具有哪些特点？','A,C','链表结点可分散存放，扩展时通常不要求搬移整个连续存储区；在已定位插入或删除位置后主要修改指针即可。链表不支持按下标O(1)随机访问，并且需要额外指针域。',1,1,1,'2026-10-08 17:23:56','2026-10-08 17:23:56'),(256,8,'MULTIPLE','关于带头结点的单链表，下列说法正确的有？','A,B,D','头结点不保存首个有效数据元素，可统一空表与非空表在表头位置的插入删除操作；空表时头结点的next通常为空。头指针指向头结点，而不是固定指向首个数据结点。',2,1,1,'2026-10-08 17:23:56','2026-10-08 17:23:56'),(257,8,'MULTIPLE','设非空循环单链表只保存尾指针rear，头结点为rear->next。下列操作中可在O(1)时间内完成的有？','A,B,D','由尾指针可直接取得头结点和首个数据结点，也能在表尾链接新结点；若删除指定值但未给出其位置，仍需遍历查找，最坏为O(n)。',3,1,1,'2026-10-08 17:23:56','2026-10-08 17:23:56'),(258,8,'JUDGE','在单链表中，已知任意数据结点p后，都可以通过复制p的后继结点数据并绕过后继结点，在O(1)时间内删除p。','FALSE','该技巧要求p存在后继结点；当p是尾结点时无法复制后继，只能从表头查找其前驱，所以不能对任意结点都保证O(1)删除。',2,1,1,'2026-10-08 17:23:56','2026-10-08 17:23:56'),(259,8,'JUDGE','两个分别含m和n个结点的有序单链表，可以复用原结点在O(m+n)时间内合并为一个有序链表，并只使用O(1)额外指针空间。','TRUE','同时扫描两条有序链表并不断链接较小结点，每个结点至多处理一次；若直接复用原结点，只需常数个工作指针。',3,1,1,'2026-10-08 17:23:56','2026-10-08 17:23:56'),(260,9,'SINGLE','队列的插入和删除操作通常遵循什么原则？','A','普通队列在队尾插入、在队头删除，先进入队列的元素先离开，因此遵循先进先出原则。',1,1,1,'2026-10-08 17:23:56','2026-10-08 17:23:56'),(261,9,'SINGLE','检查一串括号是否正确配对时，最适合保存尚未匹配左括号的数据结构是？','B','最近出现的未匹配左括号应最先与右括号配对，这符合后进先出的栈结构。',1,1,1,'2026-10-08 17:23:56','2026-10-08 17:23:56'),(262,9,'SINGLE','计算后缀表达式时，读到一个运算符后通常应如何处理操作数栈？','C','二元运算符需要先弹出右操作数，再弹出左操作数，完成运算后将结果重新压栈，最终栈顶即表达式结果。',2,1,1,'2026-10-08 17:23:56','2026-10-08 17:23:56'),(263,9,'MULTIPLE','关于栈的基本操作，下列说法正确的有？','A,C,D','入栈和出栈都在栈顶进行，顺序栈可用数组实现，链栈通常把链表表头作为栈顶以便O(1)操作；栈底元素不会总是最先删除。',1,1,1,'2026-10-08 17:23:56','2026-10-08 17:23:56'),(264,9,'MULTIPLE','设循环队列数组长度为MaxSize，并牺牲一个单元区分队空和队满。下列说法正确的有？','A,B,D','队空条件为front=rear，队满条件为(rear+1)%MaxSize=front，队列最多保存MaxSize-1个元素；入队后rear应按模运算前进。',2,1,1,'2026-10-08 17:23:56','2026-10-08 17:23:56'),(265,9,'MULTIPLE','关于递归调用与运行时栈，下列说法正确的有？','A,C,D','每次递归调用通常建立独立活动记录，保存返回地址和局部状态；递归过深可能耗尽栈空间。递归可在保持语义的前提下改写为显式栈或其他迭代控制，并非完全无法转换。',3,1,1,'2026-10-08 17:23:56','2026-10-08 17:23:56'),(266,9,'JUDGE','采用带头结点并同时保存队头、队尾指针的链队列时，正常入队和出队操作都可在O(1)时间内完成。','TRUE','入队可由队尾指针直接链接新结点，出队可由队头指针直接删除首个数据结点，操作次数不随队列长度增长。',1,1,1,'2026-10-08 17:23:56','2026-10-08 17:23:56'),(267,9,'JUDGE','用两个栈实现队列时，若仅在输出栈为空时把输入栈元素全部转移过去，则一系列入队和出队操作的均摊时间复杂度可为O(1)。','TRUE','每个元素至多进入输入栈、转移到输出栈并从输出栈弹出，各经历常数次栈操作，因此对一系列操作均摊后每次为O(1)。',3,1,1,'2026-10-08 17:23:56','2026-10-08 17:23:56'),(268,10,'SINGLE','规定根结点位于第1层，则一棵二叉树第i层最多有多少个结点？','B','二叉树每个结点最多有两个孩子，因此各层最大结点数逐层加倍，第i层最多为2^(i-1)个结点。',1,1,1,'2026-10-08 17:23:56','2026-10-08 17:23:56'),(269,10,'SINGLE','在任意非空二叉树中，叶结点数n0与度为2的结点数n2满足什么关系？','C','由二叉树边数按结点度统计可得n1+2n2=n0+n1+n2-1，整理得n0=n2+1。',1,1,1,'2026-10-08 17:23:56','2026-10-08 17:23:56'),(270,10,'SINGLE','对一棵关键字互不相同的二叉排序树进行中序遍历，得到的关键字序列是？','A','关键字互不相同时，二叉排序树满足左子树关键字小于根、右子树关键字大于根；中序遍历按左、根、右访问，因此得到严格递增序列。',2,1,1,'2026-10-08 17:23:56','2026-10-08 17:23:56'),(271,10,'SINGLE','构造哈夫曼树时，每一步应从当前结点集合中选择哪两个结点合并？','D','哈夫曼算法每次选择权值最小的两个根结点合并，新结点权值为二者之和，以获得最小带权路径长度。',2,1,1,'2026-10-08 17:23:56','2026-10-08 17:23:56'),(272,10,'MULTIPLE','关于二叉树遍历的常见实现，下列说法正确的有？','A,B,D','递归深度优先遍历依赖调用栈，非递归深度优先遍历可显式使用栈，层序遍历通常使用队列；中序遍历不要求二叉树一定是二叉排序树。',1,1,1,'2026-10-08 17:23:56','2026-10-08 17:23:56'),(273,10,'MULTIPLE','关于二叉排序树的查找、插入和删除，下列说法正确的有？','A,C,D','查找和插入沿一条从根向下的路径进行，平均性能与树高有关；删除有两个孩子的结点时可用其中序前驱或后继替换。二叉排序树不保证始终平衡，最坏可退化为链。',2,1,1,'2026-10-08 17:23:56','2026-10-08 17:23:56'),(274,10,'JUDGE','完全二叉树按层序从1开始编号并存入数组时，编号为i且i>1的结点，其双亲结点编号为floor(i/2)。','TRUE','完全二叉树的顺序存储下，结点i的左、右孩子编号分别为2i和2i+1，因此非根结点的双亲编号为floor(i/2)。',2,1,1,'2026-10-08 17:23:56','2026-10-08 17:23:56'),(275,10,'JUDGE','一棵各结点关键字互不相同的二叉树，可以由其先序遍历序列和中序遍历序列唯一确定。','TRUE','先序序列确定根结点，中序序列把其余结点划分为左、右子树；递归应用这一过程即可唯一恢复整棵树。',3,1,1,'2026-10-08 17:23:56','2026-10-08 17:23:56'),(276,11,'SINGLE','含V个顶点的图采用邻接矩阵存储时，矩阵本身的空间复杂度通常为？','C','邻接矩阵需要为每一对顶点保留一个位置，共V×V个位置，因此空间复杂度为O(V²)，与实际边数多少无关。',1,1,1,'2026-10-08 17:23:56','2026-10-08 17:23:56'),(277,11,'SINGLE','采用非递归方式实现图的深度优先搜索时，通常使用哪种辅助数据结构？','A','深度优先搜索需要优先继续访问最近发现且尚未展开的顶点，符合栈的后进先出特性。',1,1,1,'2026-10-08 17:23:56','2026-10-08 17:23:56'),(278,11,'SINGLE','一个含V个顶点的连通无向图，其任意生成树包含多少条边？','B','生成树包含原图全部V个顶点且连通无环，树的边数必为V-1。',1,1,1,'2026-10-08 17:23:56','2026-10-08 17:23:56'),(279,11,'SINGLE','使用Dijkstra算法求单源最短路径时，边权应满足的典型前提是？','D','Dijkstra算法一旦确定某顶点的最短距离就不再回退，这一贪心性质要求图中不存在负权边。',2,1,1,'2026-10-08 17:23:56','2026-10-08 17:23:56'),(280,11,'SINGLE','对有向无环图进行拓扑排序时，每次通常选择哪类顶点输出？','A','拓扑排序反复选择当前入度为0的顶点输出，并删除其出边；若所有顶点都能输出，就得到一个拓扑序列。',2,1,1,'2026-10-08 17:23:56','2026-10-08 17:23:56'),(281,11,'MULTIPLE','关于连通带权无向图的最小生成树，下列说法正确的有？','A,C,D','最小生成树包含全部顶点和V-1条边，总权值在所有生成树中最小；当边权不全相同时仍可能存在多棵等权的最小生成树，所以不一定唯一。',2,1,1,'2026-10-08 17:23:56','2026-10-08 17:23:56'),(282,11,'JUDGE','无向图的邻接矩阵一定关于主对角线对称。','TRUE','无向边连接顶点i和j时，邻接矩阵中的(i,j)与(j,i)同时表示这条边，因此矩阵关于主对角线对称。',1,1,1,'2026-10-08 17:23:56','2026-10-08 17:23:56'),(283,11,'JUDGE','一个有向图存在拓扑序列，当且仅当该图中不存在有向环。','TRUE','有向环中的顶点无法满足线性的先后约束；反之，有向无环图总能不断找到入度为0的顶点并完成拓扑排序。',3,1,1,'2026-10-08 17:23:56','2026-10-08 17:23:56'),(284,12,'SINGLE','顺序查找最适合下列哪种情况？','D','顺序查找只需逐个比较，不要求表中元素有序，也不要求采用顺序存储，因此可用于无序的顺序表或链表。',1,1,1,'2026-10-08 17:23:56','2026-10-08 17:23:56'),(285,12,'SINGLE','对线性表使用二分查找时，通常要求该表满足什么条件？','B','二分查找需要根据中间元素快速缩小到一半区间，因此通常要求元素按关键字有序且采用支持随机访问的顺序存储。',1,1,1,'2026-10-08 17:23:56','2026-10-08 17:23:56'),(286,12,'SINGLE','在散列表中，装填因子通常定义为什么？','A','装填因子等于表中已存记录数除以散列表地址空间大小，它会影响冲突概率和查找性能。',2,1,1,'2026-10-08 17:23:56','2026-10-08 17:23:56'),(287,12,'SINGLE','下列组合中，两种算法在常规实现下都具有稳定性的是？','C','直接插入排序和冒泡排序在常规实现中不会改变相等关键字的相对次序；快速排序和堆排序通常不稳定。题目要求单选，因此选项中把两个稳定算法列为一组。',2,1,1,'2026-10-08 17:23:56','2026-10-08 17:23:56'),(288,12,'SINGLE','在含15个互不相同元素的有序顺序表上进行二分查找，成功查找的最大比较次数是多少？','D','15个元素可构成4层的满判定树，最深层元素需要比较4次，因此成功查找的最大比较次数为4。',3,1,1,'2026-10-08 17:23:56','2026-10-08 17:23:56'),(289,12,'MULTIPLE','下列内部排序算法中，常规实现通常是稳定排序的有？','A,B,D','直接插入排序、冒泡排序和归并排序可保持相等关键字的原相对次序；堆排序在调整堆时可能改变该次序，通常不稳定。',1,1,1,'2026-10-08 17:23:56','2026-10-08 17:23:56'),(290,12,'MULTIPLE','关于常见排序算法的时间复杂度，下列说法正确的有？','A,C,D','直接插入排序在序列已有序时最好为O(n)；归并排序的最坏时间复杂度为O(n log n)；堆排序最坏为O(n log n)。快速排序最坏可退化为O(n²)，并非始终O(n log n)。',2,1,1,'2026-10-08 17:23:56','2026-10-08 17:23:56'),(291,12,'MULTIPLE','在只通过关键字比较来排序的模型中，下列说法正确的有？','A,B,D','比较排序在最坏情况下需要Ω(n log n)次比较；归并排序和堆排序能达到O(n log n)最坏时间。计数排序利用关键字范围而不只依赖比较，所以不受该比较下界直接限制。',3,1,1,'2026-10-08 17:23:56','2026-10-08 17:23:56'),(292,13,'SINGLE','进程从运行态因时间片用完通常转为哪种状态？','A','正确答案是“就绪态”。时间片用完后进程仍具备运行条件，只需等待处理机。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(293,13,'SINGLE','同一进程内各线程通常共享的是？','D','正确答案是“地址空间和打开文件”。线程拥有独立执行现场，但共享进程资源。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(294,13,'SINGLE','进程控制块PCB的主要作用是？','C','正确答案是“保存进程管理与运行现场信息”。操作系统依靠PCB描述和管理进程。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(295,13,'MULTIPLE','下列哪些属于进程可能经历的基本状态？','A,B,C','正确选项为“运行态、就绪态、阻塞态”。经典三状态包括运行、就绪和阻塞。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(296,13,'MULTIPLE','与进程相比，线程通常具有哪些特点？','A,B,C','正确选项为“切换开销较小、同进程线程共享多数资源、拥有独立栈”。线程保留独立执行现场，但同进程线程共享地址空间。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(297,13,'MULTIPLE','进程发生上下文切换时，操作系统通常需要保存哪些信息？','A,B,C','正确选项为“程序计数器、通用寄存器、进程状态”。恢复执行需要保存处理机现场和调度状态。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(298,13,'JUDGE','一个进程可以包含多个可并发执行的线程。','TRUE','该说法正确。线程是进程中的执行单位，一个进程可创建多个线程。',3,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(299,13,'JUDGE','进程进入阻塞态后，即使等待事件尚未发生，也可由调度程序直接选中运行。','FALSE','该说法错误。阻塞进程须先因事件完成转为就绪态，才能参与调度。',3,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(300,14,'SINGLE','先来先服务调度算法主要依据什么选择作业或进程？','C','正确答案是“到达先后顺序”。FCFS按进入队列的先后顺序服务。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(301,14,'SINGLE','时间片轮转调度最直接适用于哪类系统？','B','正确答案是“分时系统”。轮转使多个交互进程周期性获得处理机。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(302,14,'SINGLE','周转时间通常等于什么？','A','正确答案是“完成时刻减到达时刻”。周转时间覆盖作业从到达到完成的全部时间。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(303,14,'MULTIPLE','下列哪些算法可能导致长作业或低优先级进程饥饿？','A,B,C','正确选项为“短作业优先、静态优先级调度、最短剩余时间优先”。持续到来的短作业或高优先级进程可能使其他进程长期等待。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(304,14,'MULTIPLE','评价处理机调度时常用的指标有哪些？','A,B,C','正确选项为“处理机利用率、系统吞吐量、周转时间”。这些指标分别反映资源使用、处理能力和完成效率。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(305,14,'MULTIPLE','关于多级反馈队列调度，下列说法正确的有？','A,B,C','正确选项为“通常设置多个优先级队列、高优先级队列时间片可较短、进程可因用完整个时间片而降级”。反馈机制依据进程行为动态调整其队列和优先级。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(306,14,'JUDGE','抢占式调度允许操作系统在进程尚未主动放弃处理机时剥夺其运行权。','TRUE','该说法正确。时钟中断或更高优先级进程到达都可能触发抢占。',3,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(307,14,'JUDGE','响应时间是作业从提交到全部完成所经历的时间。','FALSE','该说法错误。该定义是周转时间；响应时间通常指提交请求到首次响应的间隔。',3,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(308,15,'SINGLE','临界区是指进程中哪一段代码？','A','正确答案是“访问临界资源的代码”。临界资源一次只允许有限进程访问，相关代码段需互斥执行。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(309,15,'SINGLE','记录型信号量执行P操作时，若资源不可用，调用进程通常会怎样？','D','正确答案是“进入阻塞队列”。阻塞型实现会挂起等待资源的进程。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(310,15,'SINGLE','管程把共享数据和对它的操作封装在一起，主要用于解决什么问题？','C','正确答案是“进程同步与互斥”。管程通过受控入口和条件变量组织并发访问。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(311,15,'SINGLE','避免死锁的银行家算法在分配资源前检查什么？','B','正确答案是“系统是否仍处于安全状态”。只有能保持安全序列的分配才被允许。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(312,15,'MULTIPLE','产生死锁通常必须同时满足哪些条件？','A,B,C,D','正确选项为“互斥条件、请求并保持条件、不可剥夺条件、循环等待条件”。四个必要条件同时成立时才可能产生死锁。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(313,15,'MULTIPLE','下列哪些措施可用于处理死锁？','A,B,C','正确选项为“破坏死锁必要条件进行预防、分配前进行安全性检查、检测后撤销进程或剥夺资源”。预防、避免、检测并解除是常见策略。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(314,15,'JUDGE','互斥信号量的初值通常可设为1。','TRUE','该说法正确。值为1表示临界资源初始可用，P和V操作实现互斥。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(315,15,'JUDGE','只要系统当前存在安全序列，就说明系统已经发生死锁。','FALSE','该说法错误。安全序列表明各进程存在顺序完成的可能，系统处于安全状态。',3,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(316,16,'SINGLE','分页存储管理中，逻辑地址通常由哪两部分组成？','C','正确答案是“页号和页内偏移”。页号用于查页表，偏移确定页内位置。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(317,16,'SINGLE','快表TLB的主要作用是？','B','正确答案是“缓存近期页表项以加快地址转换”。TLB命中可减少访问内存中页表的次数。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(318,16,'SINGLE','页面置换中的LRU算法选择哪一页淘汰？','A','正确答案是“最长时间未被访问的页”。LRU以近期访问历史近似程序局部性。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(319,16,'SINGLE','缺页中断发生在什么情况下？','D','正确答案是“访问页不在主存”。页表项表明目标页未装入时需调页。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(320,16,'SINGLE','段式管理中，段的划分主要反映什么？','C','正确答案是“程序的逻辑结构”。代码、数据和栈等逻辑单位可形成不同段。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(321,16,'MULTIPLE','关于虚拟存储器，下列说法正确的有？','A,B,C','正确选项为“利用局部性原理、只装入部分页面即可开始运行、逻辑地址空间可大于物理内存”。请求调页配合外存使程序按需驻留内存。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(322,16,'JUDGE','分页管理会产生外部碎片。','FALSE','该说法错误。固定大小页框避免外部碎片，但最后一页可能产生内部碎片。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(323,16,'JUDGE','在其他条件相同且未发生抖动时，给进程增加可用页框通常有助于降低缺页率。','TRUE','该说法正确。更多页框能容纳更大的工作集，一般可减少页面换入换出。',3,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(324,17,'SINGLE','文件的逻辑结构主要是从谁的视角描述文件组织？','A','正确答案是“用户和应用程序”。逻辑结构描述记录如何被用户理解和访问。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(325,17,'SINGLE','文件控制块FCB通常不包含下列哪项？','D','正确答案是“正在执行线程的寄存器值”。寄存器现场属于线程或进程上下文，不是文件元数据。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(326,17,'SINGLE','采用索引分配时，文件数据块地址主要记录在哪里？','C','正确答案是“索引块”。索引块集中保存该文件各数据块的指针。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(327,17,'SINGLE','树形目录相较单级目录的主要优点是？','B','正确答案是“便于分类并减少重名冲突”。层次目录允许不同目录中使用相同文件名并组织文件。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(328,17,'SINGLE','空闲块位示图中一个二进制位通常对应什么？','A','正确答案是“一个磁盘块”。位值表示相应磁盘块空闲或已分配。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(329,17,'MULTIPLE','文件的基本操作通常包括哪些？','A,B,C','正确选项为“创建、打开、读写”。处理机调度不属于文件接口操作。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(330,17,'MULTIPLE','关于文件链接，下列说法正确的有？','A,B,C','正确选项为“硬链接可与原名指向同一文件对象、符号链接保存目标路径信息、删除一个硬链接不必立即删除仍有链接的文件内容”。符号链接可能在目标删除后成为悬空链接。',3,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(331,17,'MULTIPLE','文件系统设置访问权限可控制哪些操作？','A,B,C','正确选项为“读取、写入、执行”。权限位控制文件访问，不控制硬件主频。',3,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(332,18,'SINGLE','OSI参考模型共有多少层？','A','正确答案是“7层”。OSI自下而上分为七个层次。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(333,18,'SINGLE','协议三要素通常是语法、语义和什么？','D','正确答案是“同步”。同步规定事件实现顺序和速度匹配。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(334,18,'SINGLE','在分层网络体系中，对等实体之间通信遵循什么？','C','正确答案是“协议”。协议规定同层对等实体交换信息的规则。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(335,18,'MULTIPLE','TCP/IP体系结构通常包括哪些层次？','A,B,C,D','正确选项为“应用层、传输层、网际层、网络接口层”。四层共同完成端到端网络通信。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(336,18,'MULTIPLE','分层体系结构的优点包括哪些？','A,B,C','正确选项为“各层功能相对独立、便于标准化、便于模块化实现与维护”。清晰接口可限制变化影响范围。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(337,18,'MULTIPLE','关于服务与协议，下列说法正确的有？','A,B,C','正确选项为“服务是下层向上层提供的功能、协议是对等实体通信规则、接口定义相邻层交互方式”。服务、协议和接口含义不同但相互配合。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(338,18,'JUDGE','网络层向传输层提供服务。','TRUE','该说法正确。在分层模型中，较低层通过接口向相邻高层提供服务。',3,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(339,18,'JUDGE','协议数据单元在各层的名称和首部完全相同。','FALSE','该说法错误。不同层会封装各自控制信息，PDU名称和格式也不同。',3,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(340,19,'SINGLE','数据链路层成帧的主要目的是什么？','C','正确答案是“划分可识别的帧边界”。接收方必须能识别一帧的开始和结束。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(341,19,'SINGLE','循环冗余校验CRC主要用于检测什么？','B','正确答案是“传输比特差错”。发送端和接收端以生成多项式进行余数校验。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(342,19,'SINGLE','以太网交换机转发表通常根据什么学习？','A','正确答案是“收到帧的源MAC地址”。交换机把源MAC与入端口的对应关系写入表项。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(343,19,'MULTIPLE','数据链路层的常见功能有哪些？','A,B,C','正确选项为“组帧、差错检测、流量控制”。进程寻址通常由传输层端口完成。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(344,19,'MULTIPLE','关于CSMA/CD，下列说法正确的有？','A,B,C','正确选项为“发送前监听信道、检测到冲突后停止发送、冲突后采用随机退避”。全双工交换链路无共享冲突，不需要CSMA/CD。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(345,19,'MULTIPLE','交换机收到目的MAC未知的单播帧时，通常会怎样处理？','A,B,C','正确选项为“除入端口外向同VLAN其他端口泛洪、记录源MAC与入端口、以后可依据学习结果定向转发”。未知单播先学习源地址，再进行泛洪。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(346,19,'JUDGE','MAC地址主要用于局域网链路层的帧转发。','TRUE','该说法正确。以太网网卡和交换机依据MAC地址识别链路层接口。',3,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(347,19,'JUDGE','CRC能够可靠纠正所有出现的比特错误。','FALSE','该说法错误。CRC主要用于检错，本身通常不负责纠正错误。',3,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(348,20,'SINGLE','IPv4地址长度是多少位？','A','正确答案是“32位”。IPv4用32位二进制数标识接口地址。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(349,20,'SINGLE','路由器转发IP分组时通常依据什么选择下一跳？','D','正确答案是“目的IP地址与路由表”。网络层按目的网络前缀进行最长匹配。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(350,20,'SINGLE','ARP协议在IPv4局域网中主要解析什么映射？','C','正确答案是“IP地址到MAC地址”。发送链路层帧前需获知下一跳的MAC地址。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(351,20,'SINGLE','一个/24的IPv4子网包含多少个地址？','B','正确答案是“256个”。主机部分有8位，共2的8次方个地址。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(352,20,'MULTIPLE','关于IP协议，下列说法正确的有？','A,B,C','正确选项为“提供无连接服务、尽力而为交付、路由器可逐跳转发分组”。可靠与有序通常由上层协议按需实现。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(353,20,'MULTIPLE','ICMP可用于哪些场景？','A,B,C','正确选项为“报告目的不可达、发送回显请求与应答、报告生存时间超时”。ICMP承载网络控制与差错报告信息，不是网页应用数据。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(354,20,'JUDGE','路由表采用最长前缀匹配时，应选择与目的地址匹配位数最多的表项。','TRUE','该说法正确。更长前缀代表更具体的路由。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(355,20,'JUDGE','IPv4分组每经过一个路由器，TTL字段通常增加1。','FALSE','该说法错误。路由器会将TTL至少减1，为0时丢弃并可发送ICMP超时报文。',3,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(356,21,'SINGLE','TCP使用什么机制标识一条连接的两个端点？','C','正确答案是“IP地址与端口号组合”。套接字端点由IP地址和端口号标识。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(357,21,'SINGLE','UDP首部的固定长度是多少字节？','B','正确答案是“8字节”。UDP首部含四个16位字段，共8字节。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(358,21,'SINGLE','TCP建立连接通常采用几次握手？','A','正确答案是“三次”。三次握手同步双方初始序号并确认收发能力。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(359,21,'SINGLE','TCP接收方通告窗口主要服务于什么控制？','D','正确答案是“流量控制”。接收窗口限制发送方未确认数据量，避免淹没接收缓存。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(360,21,'SINGLE','TCP超时重传计时器通常依据什么动态调整？','C','正确答案是“往返时间RTT估计”。RTT采样和波动用于计算合理重传超时。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(361,21,'MULTIPLE','TCP能够提供哪些特性？','A,B,C','正确选项为“可靠字节流、面向连接、按序交付”。TCP是字节流协议，不保留应用层消息边界。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(362,21,'JUDGE','UDP发送数据前必须先通过三次握手建立连接。','FALSE','该说法错误。UDP是无连接传输协议，可直接发送数据报。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(363,21,'JUDGE','TCP确认号通常表示接收方下一次期望收到的字节序号。','TRUE','该说法正确。累计确认以该序号之前的数据均已按序收到为含义。',3,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(364,22,'SINGLE','DNS的主要功能是什么？','A','正确答案是“将域名解析为IP地址等资源记录”。DNS是分布式命名系统。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(365,22,'SINGLE','HTTP默认使用的熟知端口通常是？','D','正确答案是“80”。未加密HTTP服务通常监听TCP 80端口。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(366,22,'SINGLE','HTTPS相对HTTP主要增加了什么？','C','正确答案是“TLS提供加密与身份认证”。TLS在应用数据传输前建立安全会话。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(367,22,'SINGLE','电子邮件发送协议通常是？','B','正确答案是“SMTP”。SMTP负责邮件提交和服务器间传送。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(368,22,'SINGLE','DHCP的主要作用是什么？','A','正确答案是“自动配置IP地址等网络参数”。客户端可通过DHCP获得地址、网关和DNS等配置。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(369,22,'MULTIPLE','关于HTTP，下列说法正确的有？','A,B,C','正确选项为“请求与响应由报文组成、HTTP本身是无状态协议、状态码可表示处理结果”。传统HTTP通常基于TCP，新版本也不等于强制所有报文使用UDP。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(370,22,'MULTIPLE','DNS资源记录可用于描述哪些信息？','A,B,C','正确选项为“域名对应IPv4地址、域名对应IPv6地址、邮件服务器”。A、AAAA和MX记录分别承载这些信息。',3,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(371,22,'MULTIPLE','关于电子邮件系统，下列说法正确的有？','A,B,C','正确选项为“SMTP可用于发送邮件、POP3可用于收取邮件、IMAP支持服务器端邮件管理”。邮件服务器定位可使用DNS的MX记录。',3,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(419,23,'SINGLE','极限 lim(x→∞) 1/x 的值为？','A','正确答案是“0”。分母绝对值无限增大，分式趋于0。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(420,23,'SINGLE','当x→0时，与sin x等价的无穷小是？','D','正确答案是“x”。基本等价无穷小关系为sin x～x。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(421,23,'SINGLE','函数f(x)=1/x在x=0处属于哪类间断点？','C','正确答案是“无穷间断点”。x从两侧趋近0时函数无界。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(422,23,'MULTIPLE','若lim(x→a)f(x)=A且lim(x→a)g(x)=B，则在相应运算有意义时哪些结论成立？','A,B,C','正确选项为“lim(f+g)=A+B、lim(fg)=AB、B≠0时lim(f/g)=A/B”。极限四则运算要求相关极限存在，商法则还要求分母极限非零。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(423,23,'MULTIPLE','闭区间上连续函数必具有哪些性质？','A,B,C','正确选项为“有界、能取得最大值和最小值、满足介值性质”。闭区间连续可推出有界、最值和介值，但不保证可导。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(424,23,'MULTIPLE','下列哪些极限等于1？','A,B,C','正确选项为“lim(x→0)sin x/x、lim(x→0)ln(1+x)/x、lim(x→0)(e^x-1)/x”。前三个是基本极限，1-cos x为x²量级，除以x趋于0。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(425,23,'JUDGE','若函数在x=a处可导，则它在x=a处连续。','TRUE','该说法正确。可导蕴含增量可表示为导数乘增量加高阶无穷小，故连续。',3,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(426,23,'JUDGE','两个无穷小的商一定仍是无穷小。','FALSE','该说法错误。商的极限取决于二者阶数，例如x/x恒为1。',3,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(427,24,'SINGLE','函数ln x在x>0时的导数是？','C','正确答案是“1/x”。对数函数基本求导公式为(ln x)\'=1/x。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(428,24,'SINGLE','若f\'(x0)=0且f\'\'(x0)<0，则x0通常是什么点？','B','正确答案是“严格局部极大值点”。二阶充分条件中负的二阶导数表示局部向下弯曲。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(429,24,'SINGLE','曲线y=f(x)在x=x0处切线斜率等于什么？','A','正确答案是“f\'(x0)”。导数的几何意义是切线斜率。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(430,24,'MULTIPLE','关于罗尔定理，下列条件中属于其假设的有？','A,B,C','正确选项为“在闭区间[a,b]连续、在开区间(a,b)可导、f(a)=f(b)”。前三项共同保证区间内存在导数为0的点。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(431,24,'MULTIPLE','若函数在区间内满足f\'(x)<0，则可推出哪些结论？','A,B,C','正确选项为“函数严格单调减少、任取x1<x2有f(x1)>f(x2)、区间内不存在严格递增子区间”。导数符号决定单调性，不决定函数值正负。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(432,24,'MULTIPLE','求函数极值时可能需要考察哪些点？','A,B,C','正确选项为“导数为0的点、导数不存在但函数有定义的点、区间端点上的最值问题”。临界点和端点是极值或最值分析的候选位置。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(433,24,'JUDGE','函数在一点取得局部极值，则该点的导数一定存在且等于0。','FALSE','该说法错误。极值点可能不可导，例如绝对值函数在0处取得极小值。',3,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(434,24,'JUDGE','若f\'\'(x)>0在区间内恒成立，则f\'(x)在该区间严格增加。','TRUE','该说法正确。f\'\'是f\'的导数，恒正说明f\'严格单调增加。',3,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(435,25,'SINGLE','不定积分∫cos x dx等于？','A','正确答案是“sin x+C”。sin x的导数为cos x。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(436,25,'SINGLE','定积分∫[0,2] x dx的值为？','D','正确答案是“2”。原函数为x²/2，代入上下限得到2。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(437,25,'SINGLE','若F\'(x)=f(x)，则∫f(x)dx可写为？','C','正确答案是“F(x)+C”。不定积分表示全体原函数，彼此相差常数。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(438,25,'SINGLE','分部积分公式∫u dv等于？','B','正确答案是“uv-∫v du”。由乘积求导公式积分得到分部积分公式。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(439,25,'MULTIPLE','关于定积分性质，下列说法正确的有？','A,B,C','正确选项为“∫[a,a]f(x)dx=0、交换上下限积分变号、被积函数非负时积分非负”。最后一式混淆了被积函数与原函数。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(440,25,'MULTIPLE','计算定积分时可采用哪些方法？','A,B,C','正确选项为“换元法、分部积分法、利用对称性”。换元时必须同步处理变量和上下限，交换上下限需变号。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(441,25,'JUDGE','若连续函数f在[a,b]上恒正且a<b，则∫[a,b]f(x)dx>0。','TRUE','该说法正确。连续正函数在非退化闭区间上的积分严格为正。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(442,25,'JUDGE','不定积分的结果是唯一的一个函数。','FALSE','该说法错误。同一被积函数的原函数族相差任意常数。',3,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(443,26,'SINGLE','函数z=x²y在点(1,2)处对x的偏导数为？','C','正确答案是“4”。对x求偏导得2xy，代入(1,2)为4。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(444,26,'SINGLE','函数z=x²+y²的梯度为？','B','正确答案是“(2x,2y)”。梯度由各一阶偏导数组成。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(445,26,'SINGLE','二元函数在一点可微能够推出什么？','A','正确答案是“在该点连续”。多元函数可微是比连续更强的局部性质。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(446,26,'SINGLE','若z=f(x,y)，x=x(t)，y=y(t)，则dz/dt等于？','D','正确答案是“f_x x\'(t)+f_y y\'(t)”。多元复合函数按链式法则求导。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(447,26,'SINGLE','求闭区域上连续函数的最大最小值时，除内部驻点外还应考察哪里？','C','正确答案是“区域边界”。全局最值也可能出现在边界。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(448,26,'MULTIPLE','设二元函数在点处具有连续的一阶偏导数，可推出哪些结论？','A,B,C','正确选项为“在该点可微、在该点连续、偏导数存在”。连续偏导是可微的充分条件，但与是否极值无必然关系。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(449,26,'JUDGE','二元函数在一点两个偏导数都存在，就一定在该点可微。','FALSE','该说法错误。偏导存在不足以保证全增量具有线性主部。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(450,26,'JUDGE','梯度方向是在给定点方向导数增长最快的方向。','TRUE','该说法正确。非零梯度方向取得最大的单位方向导数。',3,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(451,27,'SINGLE','微分方程y\'=3x²的通解是？','A','正确答案是“y=x³+C”。对3x²积分得到x³+C。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(452,27,'SINGLE','一阶线性微分方程的标准形式通常写为？','D','正确答案是“y\'+P(x)y=Q(x)”。一阶线性方程对y及其导数均为一次。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(453,27,'SINGLE','方程y\'=ky的通解是？','C','正确答案是“y=Ce^(kx)”。分离变量或特征形式可得指数解。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(454,27,'SINGLE','二阶常系数齐次线性方程y\'\'+ay\'+by=0的求解通常先建立什么？','B','正确答案是“特征方程r²+ar+b=0”。指数试探解把微分方程化为代数方程。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(455,27,'SINGLE','方程y\'\'=0的通解是？','A','正确答案是“y=C1x+C2”。连续积分两次得到一次函数族。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(456,27,'MULTIPLE','关于微分方程通解与特解，下列说法正确的有？','A,B,C','正确选项为“通解通常含足够个独立常数、初始条件可用于确定常数、特解满足原方程”。特解必须代入后满足方程，初值问题由条件筛选解。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(457,27,'MULTIPLE','方程y\'\'-y=0的解包括哪些？','A,B,C','正确选项为“e^x、e^(-x)、C1e^x+C2e^(-x)”。特征根为1和-1，通解是相应指数解的线性组合。',3,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(458,27,'MULTIPLE','求可分离变量方程时通常包含哪些步骤？','A,B,C','正确选项为“把y项与x项分居等式两侧、两边积分、必要时利用初始条件确定常数”。分离、积分和定常数构成标准过程。',3,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(459,28,'SINGLE','元素按行依次为a、b、c、d的二阶行列式，其值为？','A','正确答案是“ad-bc”。二阶行列式按主对角线积减副对角线积计算。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(460,28,'SINGLE','若行列式有两行完全相同，则其值为？','D','正确答案是“0”。交换这两行既应变号又不改变行列式，只能为0。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(461,28,'SINGLE','把行列式某一行乘以常数k，行列式如何变化？','C','正确答案是“变为原来的k倍”。行列式对任一行具有齐次性。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(462,28,'MULTIPLE','下列哪些操作不改变行列式的值？','A,B,C','正确选项为“某行加上另一行的k倍、某列加上另一列的k倍、同时对矩阵作一次初等行倍加”。倍加变换不改值，交换两行使行列式变号。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(463,28,'MULTIPLE','关于行列式，下列说法正确的有？','A,B,C','正确选项为“det(AB)=det(A)det(B)、det(A^T)=det(A)、A可逆时det(A)≠0”。行列式不具一般加法线性。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(464,28,'MULTIPLE','若n阶方阵A的det(A)=0，则可推出哪些结论？','A,B,C','正确选项为“A不可逆、A的行向量线性相关、rank(A)<n”。行列式为0等价于不满秩，齐次方程存在非零解。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(465,28,'JUDGE','行列式按任意一行展开所得结果相同。','TRUE','该说法正确。拉普拉斯展开可沿任意行或列进行，值不变。',3,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(466,28,'JUDGE','矩阵A的行列式与其转置矩阵的行列式互为相反数。','FALSE','该说法错误。转置不改变行列式，det(A^T)=det(A)。',3,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(467,29,'SINGLE','单位矩阵E与同阶矩阵A相乘的结果是？','C','正确答案是“A”。单位矩阵是矩阵乘法的单位元。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(468,29,'SINGLE','若A为m×n矩阵，B为n×p矩阵，则AB的阶数为？','B','正确答案是“m×p”。结果的行数取A，列数取B。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(469,29,'SINGLE','可逆矩阵A满足A^(-1)A等于？','A','正确答案是“E”。逆矩阵定义给出左右乘积均为单位矩阵。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(470,29,'MULTIPLE','关于矩阵运算，下列说法正确的有？','A,B,C','正确选项为“矩阵加法满足交换律、矩阵乘法满足结合律、一般AB不等于BA”。矩阵乘法通常不可交换。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(471,29,'MULTIPLE','若A和B均为同阶可逆矩阵，则哪些结论正确？','A,B,C','正确选项为“AB可逆、(AB)^(-1)=B^(-1)A^(-1)、A^T可逆”。可逆矩阵之和可能奇异，例如B=-A。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(472,29,'MULTIPLE','初等矩阵具有哪些性质？','A,B,C','正确选项为“可由单位矩阵作一次初等变换得到、一定可逆、左乘矩阵对应行变换”。初等矩阵不必对称。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(473,29,'JUDGE','若AB=0，则必有A=0或B=0。','FALSE','该说法错误。矩阵乘法存在非零零因子。',3,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(474,29,'JUDGE','可逆矩阵的逆矩阵仍然可逆。','TRUE','该说法正确。A的逆的逆等于A。',3,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(475,30,'SINGLE','零向量与任意向量组组成的新向量组一定怎样？','A','正确答案是“线性相关”。令零向量系数非零而其他系数为0即可得到非平凡零组合。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(476,30,'SINGLE','n维向量空间中，任意n+1个向量一定怎样？','D','正确答案是“线性相关”。向量个数超过空间维数时必线性相关。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(477,30,'SINGLE','向量组的秩等于什么？','C','正确答案是“其极大线性无关组所含向量数”。这是向量组秩的定义。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(478,30,'SINGLE','两个非零向量正交意味着它们的内积为？','B','正确答案是“0”。欧氏空间中正交以标准内积为0刻画。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(479,30,'MULTIPLE','关于线性无关向量组，下列说法正确的有？','A,B,C','正确选项为“任一子组仍线性无关、零向量不在其中、其向量表示系数具有唯一性”。新增向量若在原组张成空间内会导致相关。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(480,30,'MULTIPLE','若向量β可由α1,α2,α3线性表示，则哪些说法正确？','A,B,C','正确选项为“β属于它们张成的空间、加入β后向量组的秩不增加、存在系数使β等于其线性组合”。可表示性并不能保证原三个向量无关。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(481,30,'JUDGE','等价向量组必具有相同的秩。','TRUE','该说法正确。相互可线性表示使二者张成同一子空间，维数相同。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(482,30,'JUDGE','三个两两不平行的三维向量一定线性无关。','FALSE','该说法错误。三个向量可能共面但两两不平行，仍线性相关。',3,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(483,31,'SINGLE','非齐次线性方程组Ax=b无解的判据是？','C','正确答案是“rank(A)<rank(A,b)”。系数矩阵秩小于增广矩阵秩时方程矛盾。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(484,31,'SINGLE','含n个未知量的齐次方程组Ax=0仅有零解的充要条件是？','B','正确答案是“rank(A)=n”。满列秩使自由变量个数为0。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(485,31,'SINGLE','非齐次方程组的两个解之差是什么方程组的解？','A','正确答案是“对应齐次方程组”。A(x1-x2)=b-b=0。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(486,31,'SINGLE','若Ax=b有一个特解η，Ax=0的基础解系为ξ1,…,ξk，则通解形式是？','D','正确答案是“η+c1ξ1+…+ckξk”。非齐次通解等于一个特解加齐次通解。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(487,31,'SINGLE','齐次方程组基础解系所含向量个数等于？','C','正确答案是“n-rank(A)”。解空间维数由秩零化度定理给出。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(488,31,'MULTIPLE','对增广矩阵作初等行变换时，下列说法正确的有？','A,B,C','正确选项为“不改变方程组解集、可化为阶梯形分析秩、可用于求通解”。删除非零约束可能扩大解集。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(489,31,'JUDGE','若非齐次线性方程组有两个不同解，则它一定有无穷多个解。','TRUE','该说法正确。两解之差给出非零齐次解，沿该方向可构造无穷多个解。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(490,31,'JUDGE','齐次线性方程组可能没有任何解。','FALSE','该说法错误。齐次方程组总有零解。',3,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(491,32,'SINGLE','方阵A的特征值λ满足哪个方程？','A','正确答案是“det(λE-A)=0”。特征方程来自非零解(λE-A)x=0的条件。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(492,32,'SINGLE','三角矩阵的特征值是什么？','D','正确答案是“主对角线元素”。特征行列式仍为三角形，其根是对角元。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(493,32,'SINGLE','若λ是可逆矩阵A的特征值，则λ满足什么？','C','正确答案是“λ≠0”。可逆矩阵行列式非零，因此没有零特征值。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(494,32,'SINGLE','实二次型x^TAx通常可把系数矩阵取为什么矩阵？','B','正确答案是“实对称矩阵”。交叉项系数可平均到对称位置，得到等价对称矩阵。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(495,32,'SINGLE','正定二次型在任意非零实向量x上满足什么？','A','正确答案是“x^TAx>0”。正定性的定义要求所有非零向量取正值。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(496,32,'MULTIPLE','相似矩阵必具有哪些相同量？','A,B,C','正确选项为“特征多项式、特征值及代数重数、行列式”。相似不要求矩阵元素逐项相同。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(497,32,'MULTIPLE','关于实对称矩阵，下列说法正确的有？','A,B,C','正确选项为“特征值全为实数、不同特征值的特征向量正交、可正交对角化”。只有正定实对称矩阵才保证特征值全正。',3,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(498,32,'MULTIPLE','判断实对称矩阵正定可采用哪些等价条件？','A,B,C','正确选项为“所有特征值均为正、各阶顺序主子式均为正、二次型对非零向量恒正”。仅最高阶行列式为正不足以保证正定。',3,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(546,33,'SINGLE','Choose the best word: The new policy is intended to ___ innovation among small firms.','A','正确答案是“encourage”。Encourage means to promote or support an activity.',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(547,33,'SINGLE','Choose the closest meaning of “decline” in “sales began to decline”.','D','正确答案是“decrease”。As a verb here, decline means become smaller or weaker.',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(548,33,'MULTIPLE','Which words can mean “clear” in a formal explanation?','A,B,C','正确选项为“explicit、unambiguous、lucid”。The first three express clarity, while obscure means unclear.',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(549,33,'MULTIPLE','Which words appropriately complete “The evidence ___ the conclusion”?','A,B,C','正确选项为“supports、confirms、strengthens”。Support, confirm and strengthen collocate with evidence and conclusions.',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(550,33,'MULTIPLE','Which pairs are close in meaning in the stated context?','A,B,C','正确选项为“rapid—swift、purchase—buy、assist—help”。Scarce and abundant are opposites rather than synonyms.',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(551,33,'JUDGE','The word “issue” can mean either a topic or a problem, depending on context.','TRUE','该说法正确。English words may have several context-dependent senses.',3,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(552,33,'JUDGE','“Eventually” and “possibly” always have the same meaning.','FALSE','该说法错误。Eventually concerns what happens in the end; possibly expresses uncertainty.',3,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(553,34,'SINGLE','Choose the correct form: By the time we arrived, the lecture ___.','D','正确答案是“had begun”。The earlier past action takes the past perfect.',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(554,34,'SINGLE','If I ___ the answer, I would tell you.','B','正确答案是“knew”。An unreal present condition uses the simple past in the if-clause.',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(555,34,'MULTIPLE','Which sentences correctly use relative clauses?','A,B,C','正确选项为“The book that I borrowed was useful.、The student who won thanked her teacher.、The town where he grew up has changed.”。The last sentence needs whose author.',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(556,34,'MULTIPLE','Which sentences contain correct subject-verb agreement?','A,B,C','正确选项为“Each of the plans has merits.、Neither answer is complete.、A number of students are waiting.”。Results is plural and requires show.',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(557,34,'JUDGE','A modal verb is normally followed by the base form of a lexical verb.','TRUE','该说法正确。Forms such as can go and should study use the bare infinitive.',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(558,34,'JUDGE','The sentence “He suggested me to leave” is standard formal English.','FALSE','该说法错误。Use “suggested that I leave” or “suggested leaving.”',3,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(559,35,'SINGLE','Choose the standard collocation.','C','正确答案是“pose a challenge”。Pose a challenge is an established formal collocation.',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(560,35,'SINGLE','Choose the correct preposition: She is capable ___ solving the problem.','B','正确答案是“of”。Capable is followed by of plus a noun or gerund.',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(561,35,'SINGLE','Choose the best phrase: The change will ___ effect next month.','A','正确答案是“take”。Take effect means begin to operate.',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(562,35,'SINGLE','Choose the standard expression meaning “consider”.','D','正确答案是“take into account”。Take something into account is the established phrase.',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(563,35,'SINGLE','Choose the phrase that means “because of”.','C','正确答案是“due to”。Due to introduces a cause.',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(564,35,'MULTIPLE','Which expressions are standard collocations?','A,B,C','正确选项为“reach a conclusion、draw attention to、meet a requirement”。The natural collocation is make a decision, not pay a decision.',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(565,35,'JUDGE','“Contribute to” may be followed by a noun or an -ing form.','TRUE','该说法正确。The to in this phrase is a preposition.',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(566,35,'JUDGE','“Be responsible of” is the standard phrase for having responsibility.','FALSE','该说法错误。The standard phrase is be responsible for.',3,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(567,36,'SINGLE','Which connector most clearly introduces a contrast?','A','正确答案是“however”。However signals a contrast with the preceding statement.',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(568,36,'SINGLE','Which connector most clearly introduces an example?','D','正确答案是“for instance”。For instance introduces a specific illustration.',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(569,36,'SINGLE','Which word best completes the logic: The road was closed; ___, we took another route.','C','正确答案是“therefore”。The second action is a consequence of the closure.',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(570,36,'SINGLE','Which reference word can replace a previously mentioned plural noun phrase?','B','正确答案是“they”。They is the plural third-person pronoun.',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(571,36,'SINGLE','Which sentence best serves as a topic sentence for a paragraph about sleep benefits?','A','正确答案是“Adequate sleep supports both memory and emotional health.”。A topic sentence states the paragraph\'s controlling idea.',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(572,36,'MULTIPLE','Which devices can improve cohesion in a paragraph?','A,B,C','正确选项为“pronoun reference、repetition of key terms when useful、logical connectors”。Reference, controlled repetition and connectors link ideas coherently.',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(573,36,'MULTIPLE','Which connectors can signal addition?','A,B,C','正确选项为“moreover、furthermore、in addition”。On the contrary signals opposition, not addition.',3,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(574,36,'MULTIPLE','Which revisions reduce unclear reference?','A,B,C','正确选项为“replace an ambiguous “it” with the exact noun、keep pronoun number consistent、place a modifier near what it modifies”。Explicit and nearby references make relationships easier to follow.',3,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(575,37,'SINGLE','Read: “Community gardens supply fresh food, create social ties and turn unused land into green space.” What is the main idea?','A','正确答案是“Community gardens bring several local benefits.”。All listed details support the benefits of community gardens.',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(576,37,'SINGLE','Read: “Digital notes are easy to search, while handwritten notes may promote deeper processing. The best method depends on the task.” Which title is best?','D','正确答案是“Choosing a Note-Taking Method”。The passage compares methods and gives a balanced conclusion.',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(577,37,'MULTIPLE','Which clues often help identify a passage\'s main idea?','A,B,C','正确选项为“repeated key concepts、the topic sentence、the concluding summary”。Central ideas recur and frame the passage; a minor detail alone is insufficient.',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(578,37,'MULTIPLE','Which statements about a good title are correct?','A,B,C','正确选项为“It reflects the central topic.、It is neither too broad nor too narrow.、It covers the author\'s main focus.”。A title summarizes the focus without requiring verbatim repetition.',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(579,37,'MULTIPLE','Which options are likely to be distractors in a main-idea question?','A,B,C','正确选项为“a true but minor detail、a claim broader than the passage、a claim contradicting the passage”。The last option describes a plausible correct answer rather than a distractor.',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(580,37,'JUDGE','A passage\'s main idea may be implied rather than stated in one sentence.','TRUE','该说法正确。Readers may need to synthesize repeated evidence and conclusions.',3,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(581,37,'JUDGE','The longest answer choice is always the correct main idea.','FALSE','该说法错误。Answer length is not evidence of accuracy or coverage.',3,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(582,38,'SINGLE','Read: “The workshop begins at 9:30 and registration closes at 9:15.” When does registration close?','D','正确答案是“9:15”。The passage states the registration deadline directly.',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(583,38,'SINGLE','Read: “Only members may borrow cameras, but anyone may attend the training session.” Who may attend the training?','C','正确答案是“Anyone”。The second clause explicitly opens training to everyone.',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(584,38,'SINGLE','Read: “The trial included 240 adults, half of whom received the new program.” How many received the program?','B','正确答案是“120”。Half of 240 is 120.',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(585,38,'MULTIPLE','Which steps help verify a detail answer?','A,B,C','正确选项为“locate the relevant sentence、check nearby qualifications、compare paraphrases carefully”。Accurate detail reading uses context and meaning rather than word matching alone.',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(586,38,'MULTIPLE','Which words commonly signal limits or exceptions in detail questions?','A,B,C','正确选项为“only、unless、except”。These words narrow a claim; always may instead make an option overly absolute.',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(587,38,'JUDGE','A detail answer may use different wording while preserving the passage\'s meaning.','TRUE','该说法正确。Correct choices often paraphrase rather than copy the source.',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(588,38,'JUDGE','If an option contains a fact mentioned somewhere in the passage, it must answer the question asked.','FALSE','该说法错误。The fact may be irrelevant to the specific question or relationship.',3,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(589,39,'SINGLE','Read: “Maya checked the train app twice and left home earlier than usual.” What is most reasonably inferred?','C','正确答案是“She wanted to reduce the risk of being late.”。Her checking and early departure suggest concern about timing.',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(590,39,'SINGLE','Read: “The café added outdoor heaters after customers stopped using the patio in winter.” Why were heaters likely added?','B','正确答案是“To make winter patio use more comfortable”。The action responds directly to reduced cold-weather use.',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(591,39,'SINGLE','If an author describes a proposal as “promising but untested,” what is the likely attitude?','A','正确答案是“cautiously positive”。Promising is positive, while untested adds caution.',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(592,39,'SINGLE','Read: “No reminder was sent, yet nearly all volunteers arrived on time.” What can be inferred?','D','正确答案是“The volunteers probably remembered the schedule.”。Timely attendance without reminders implies prior awareness.',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(593,39,'SINGLE','Which inference is strongest when a study reports correlation only?','C','正确答案是“The variables are associated, but causation is not established.”。Correlation supports association but not a definite causal claim.',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(594,39,'MULTIPLE','Sound inferences should be based on which sources?','A,B,C','正确选项为“explicit textual clues、logical relations in the passage、the author\'s wording and tone”。Inference extends evidence cautiously without replacing it with personal beliefs.',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(595,39,'JUDGE','An inference may be valid even if it is not stated word for word.','TRUE','该说法正确。It must follow reasonably from textual evidence.',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(596,39,'JUDGE','A reasonable inference can contradict an explicit statement in the passage.','FALSE','该说法错误。An inference must remain consistent with the text.',3,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(597,40,'SINGLE','In “The device is compact, so it fits easily in a pocket,” “compact” most nearly means what?','A','正确答案是“small”。The result clause about fitting in a pocket indicates small size.',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(598,40,'SINGLE','In “The medicine alleviated the pain, allowing her to rest,” “alleviated” means what?','D','正确答案是“reduced”。Being able to rest suggests the pain became less severe.',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(599,40,'SINGLE','In “Unlike the rigid old schedule, the new plan is flexible,” “rigid” most nearly means what?','C','正确答案是“inflexible”。The contrast with flexible identifies the opposite sense.',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(600,40,'SINGLE','Which context clue is used in “Arid regions, or extremely dry areas, receive little rain”?','B','正确答案是“definition or restatement”。The phrase after or directly explains arid.',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(601,40,'SINGLE','In “His response was brief but pertinent to the question,” “pertinent” means what?','A','正确答案是“relevant”。Pertinent describes a response directly related to the question.',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(602,40,'MULTIPLE','Which clues can help infer an unfamiliar word\'s meaning?','A,B,C','正确选项为“contrast markers、examples、definitions in apposition”。Semantic and structural context provide evidence; font style normally does not.',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(603,40,'MULTIPLE','When guessing word meaning, which practices are appropriate?','A,B,C','正确选项为“identify the word\'s part of speech、test the inferred meaning in the sentence、use surrounding logic”。Morphology can also be useful, so it should not be ignored.',3,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(604,40,'MULTIPLE','Which statements about polysemy are correct?','A,B,C','正确选项为“a word may have several senses、context selects the relevant sense、dictionary order alone does not determine the passage meaning”。Multiple senses require contextual selection.',3,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(605,41,'SINGLE','In “The rapid growth of online services has changed consumer habits,” what is the main subject?','A','正确答案是“The rapid growth of online services”。The full noun phrase before has changed is the subject.',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(606,41,'SINGLE','In “What the researchers discovered surprised the public,” what is the main predicate?','D','正确答案是“surprised”。The subject clause is followed by the main predicate surprised.',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(607,41,'MULTIPLE','Which elements belong to the backbone of “The report published yesterday offers useful guidance”?','A,B,C','正确选项为“The report、offers、useful guidance”。Published yesterday is a reduced modifier, not the main predicate.',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(608,41,'MULTIPLE','Which steps help locate a long sentence\'s main clause?','A,B,C','正确选项为“identify finite verbs、separate subordinate markers、find the subject linked to the main finite verb”。Nonfinite forms do not automatically function as the main predicate.',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(609,41,'MULTIPLE','Which groups can function as a sentence subject?','A,B,C','正确选项为“a noun phrase、a gerund phrase、a what-clause”。Noun-like phrases and clauses can occupy subject position.',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(610,41,'JUDGE','A long prepositional phrase between subject and verb does not change the true grammatical subject.','TRUE','该说法正确。Modifiers may interrupt the backbone without replacing its subject.',3,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(611,41,'JUDGE','Every verb-looking word in an English sentence is a finite predicate.','FALSE','该说法错误。Participles and infinitives are nonfinite and may act as modifiers or complements.',3,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(612,42,'SINGLE','In “The fact that the plan failed surprised us,” the that-clause explains what?','D','正确答案是“the content of the fact”。The clause is appositive to fact.',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(613,42,'SINGLE','In “Although it was raining, they continued the match,” what relation does although express?','C','正确答案是“concession”。Although introduces a concessive clause.',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(614,42,'SINGLE','Which translation best renders “The book that you recommended is out of print”?','B','正确答案是“你推荐的那本书已经绝版。”。The relative clause modifies the book and should precede it naturally in Chinese.',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(615,42,'MULTIPLE','Which relations may be expressed by adverbial clauses?','A,B,C','正确选项为“time、condition、concession”。Adverbial clauses commonly express time, condition and concession.',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(616,42,'MULTIPLE','Which practices help translate relative clauses?','A,B,C','正确选项为“identify the antecedent、determine whether the clause is restrictive、adjust word order for natural Chinese”。Relative words often need structural rather than word-for-word rendering.',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(617,42,'JUDGE','A that-clause may function as a subject, object or appositive clause in different sentences.','TRUE','该说法正确。Its grammatical role depends on where it appears and what it completes.',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(618,42,'JUDGE','All English subordinate clauses must remain after the main clause in Chinese translation.','FALSE','该说法错误。Chinese word order may be adjusted to express logical relations naturally.',3,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(619,43,'SINGLE','Which Chinese translation best matches “give rise to”?','C','正确答案是“引起；导致”。The phrase introduces a result or consequence.',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(620,43,'SINGLE','Which translation best matches “in terms of”?','B','正确答案是“就……而言”。It specifies the aspect or perspective under discussion.',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(621,43,'SINGLE','Which translation best matches “be subject to” in “prices are subject to change”?','A','正确答案是“可能受……影响；取决于”。Here it means liable to or governed by a condition.',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(622,43,'SINGLE','Which translation best matches “account for” in “This factor accounts for the difference”?','D','正确答案是“解释；说明”。Account for means explain in this context.',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(623,43,'SINGLE','Which translation best matches “rather than”?','C','正确答案是“而不是”。The phrase contrasts a preferred or actual item with another.',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(624,43,'MULTIPLE','Which expression-translation pairs are appropriate?','A,B,C','正确选项为“as a result：因此、with regard to：关于、in the long run：从长远来看”。By no means means 决不, not by many methods.',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(625,43,'JUDGE','The meaning of a fixed expression should be determined as a whole rather than by translating each word separately.','TRUE','该说法正确。Idiomatic combinations often cannot be reconstructed word for word.',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(626,43,'JUDGE','“On the other hand” normally means “总而言之”.','FALSE','该说法错误。It introduces another contrasting aspect, commonly translated as 另一方面.',3,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(627,44,'SINGLE','Which Chinese order is usually natural for an English relative clause that briefly modifies a noun?','A','正确答案是“把修饰语放在中心名词之前”。Short attributive clauses are often placed before the noun in Chinese.',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(628,44,'SINGLE','When translating an English passive without an important agent, a natural Chinese choice may be what?','D','正确答案是“use an active or subjectless construction”。Chinese can foreground the event without mechanically preserving passive form.',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(629,44,'SINGLE','Which translation best handles “It is widely believed that exercise benefits health”?','C','正确答案是“人们普遍认为，锻炼有益健康。”。The formal subject it is restructured into a natural Chinese impersonal statement.',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(630,44,'SINGLE','For a very long sentence, which strategy is most reliable first?','B','正确答案是“identify logical groups and the main clause”。Structural analysis prevents relations from being lost.',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(631,44,'SINGLE','Which item most often needs explicit recovery in Chinese when English omits repeated material?','A','正确答案是“contextually omitted information needed for clarity”。Selective addition can clarify ellipsis without overtranslation.',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(632,44,'MULTIPLE','Which adjustments may produce a natural Chinese translation while preserving meaning?','A,B,C','正确选项为“reorder clauses by logic、convert passive to active when suitable、split an overly long sentence”。Structural adjustment is allowed, but meaning and stance must remain.',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(633,44,'MULTIPLE','Which principles guide sentence reorganization?','A,B,C','正确选项为“preserve logical relations、keep referents clear、respect Chinese information flow”。Faithfulness concerns meaning, not rigid surface order.',3,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(634,44,'MULTIPLE','Which signs suggest a long sentence may be split in translation?','A,B,C','正确选项为“several independent logical units、multiple layered modifiers、a clear shift from cause to result”。Distinct semantic units often benefit from controlled segmentation.',3,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(635,45,'SINGLE','Which sentence politely requests information?','A','正确答案是“Could you please provide further details about the schedule?”。The modal and please create an appropriate formal request.',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(636,45,'SINGLE','Which opening suits a letter of apology?','D','正确答案是“I am writing to apologize for the delay.”。It states the apologetic purpose directly and formally.',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(637,45,'MULTIPLE','A formal invitation should normally include which information?','A,B,C','正确选项为“purpose of the event、date and place、a polite request for attendance”。Recipients need essential event details and a courteous invitation.',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(638,45,'MULTIPLE','Which features improve a recommendation letter?','A,B,C','正确选项为“clear relationship to the candidate、specific supporting evidence、appropriate formal tone”。Credible recommendations connect evaluation to concrete evidence.',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(639,45,'MULTIPLE','Which closings are polite in formal correspondence?','A,B,C','正确选项为“I would appreciate your consideration.、Thank you for your time.、I look forward to your reply.”。The first three are courteous and conventional.',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(640,45,'JUDGE','An application letter should make its purpose clear near the beginning.','TRUE','该说法正确。Early purpose helps the reader understand the request efficiently.',3,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(641,45,'JUDGE','Informal slang is always appropriate in a formal notice.','FALSE','该说法错误。Register should suit the public and institutional context.',3,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(642,46,'SINGLE','A percentage rises from 30% to 45%. What is the increase in percentage points?','D','正确答案是“15 percentage points”。Subtracting the percentages gives a 15-point increase.',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(643,46,'SINGLE','Which sentence objectively describes a downward trend?','C','正确答案是“The figure declined steadily from 80 to 55.”。The sentence reports direction and values without unsupported judgment.',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(644,46,'SINGLE','Which sentence best states an overall trend?','B','正确答案是“Overall, participation increased despite a brief fall in 2024.”。An overview summarizes the dominant pattern and notable exception.',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(645,46,'MULTIPLE','Which comparisons are useful in a chart essay?','A,B,C','正确选项为“highest versus lowest categories、changes over time、notable similarities or gaps”。Selection should focus on meaningful quantitative relationships.',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(646,46,'MULTIPLE','Which verbs can describe an increase?','A,B,C','正确选项为“rise、grow、climb”。Plunge normally describes a sharp decrease.',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(647,46,'JUDGE','If a value doubles, it has increased by 100 percent relative to the original value.','TRUE','该说法正确。The increase equals the entire original amount.',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(648,46,'JUDGE','A chart essay should invent causes even when no evidence or prompt supports them.','FALSE','该说法错误。Explanations should be qualified and grounded in the task or reasonable evidence.',3,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(649,47,'SINGLE','Choose the correct sentence.','C','正确答案是“There are several reasons for this change.”。A plural subject takes are and countable reasons takes several.',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(650,47,'SINGLE','Choose the correct collocation.','B','正确答案是“conduct research”。Conduct research is standard formal English.',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(651,47,'SINGLE','Which sentence uses punctuation correctly?','A','正确答案是“However, the result remained uncertain.”。A sentence adverb at the start is followed by a comma.',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(652,47,'SINGLE','Choose the correct form: The results are ___ with the earlier findings.','D','正确答案是“consistent”。The adjective consistent is followed by with.',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(653,47,'SINGLE','Which sentence avoids a dangling modifier?','C','正确答案是“After reviewing the data, the researchers revised the report.”。The stated subject researchers logically performs reviewing.',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(654,47,'MULTIPLE','Which editing checks improve grammatical accuracy?','A,B,C','正确选项为“subject-verb agreement、article use、verb tense consistency”。Accuracy depends on grammar and usage, not unnecessary complexity.',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(655,47,'JUDGE','The uncountable noun “information” normally does not take the plural form “informations.”','TRUE','该说法正确。Use information or pieces of information.',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(656,47,'JUDGE','Using a rarer synonym always makes a sentence more accurate.','FALSE','该说法错误。Synonyms differ in register, collocation and precise meaning.',3,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(657,48,'SINGLE','What is the main role of a thesis statement?','A','正确答案是“state the essay\'s central claim or focus”。It guides the organization and argument of the essay.',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(658,48,'SINGLE','Where is a topic sentence commonly placed in a straightforward paragraph?','D','正确答案是“near the beginning”。An early topic sentence frames the supporting details.',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(659,48,'SINGLE','Which order best suits a problem-solution paragraph?','C','正确答案是“present the problem, analyze it, then propose a solution”。The sequence creates a clear logical progression.',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(660,48,'SINGLE','What should a conclusion usually do?','B','正确答案是“summarize or reinforce the main point without adding an unrelated argument”。A conclusion closes the established line of discussion.',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(661,48,'SINGLE','Which transition best introduces a consequence?','A','正确答案是“as a result”。As a result explicitly marks consequence.',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(662,48,'MULTIPLE','A coherent body paragraph usually contains which elements?','A,B,C','正确选项为“a controlling idea、relevant evidence or examples、explanation linking evidence to the point”。Unity requires all supporting material to serve one point.',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(663,48,'MULTIPLE','Which methods can organize an essay logically?','A,B,C','正确选项为“chronological order、cause and effect、comparison and contrast”。These recognized patterns make relationships predictable.',3,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(664,48,'MULTIPLE','Which revisions improve paragraph unity?','A,B,C','正确选项为“remove irrelevant sentences、add a clear topic sentence、group related evidence together”。Unity and coherence improve when all material supports the controlling idea.',3,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(673,49,'SINGLE','马克思主义哲学认为，物质的唯一特性是？','A','正确答案是“客观实在性”。客观实在性把物质同意识区别开来。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(674,49,'SINGLE','意识产生和发展的决定性因素是？','D','正确答案是“社会实践”。劳动和社会实践推动语言与意识形成。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(675,49,'SINGLE','正确发挥主观能动性的前提是？','C','正确答案是“尊重客观规律”。能动活动必须以客观实际和规律为依据。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(676,49,'MULTIPLE','关于物质和运动，下列说法正确的有？','A,B,C','正确选项为“运动是物质的根本属性、物质是运动的承担者、静止是运动的特殊状态”。物质与运动不可分，静止具有相对性。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(677,49,'MULTIPLE','意识的能动作用表现在哪些方面？','A,B,C','正确选项为“有目的地认识世界、能动地改造世界、调控人的行为和生理活动”。意识作用需通过实践并受客观规律制约。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(678,49,'MULTIPLE','一切从实际出发要求做到哪些？','A,B,C','正确选项为“尊重客观事实、把握客观规律、发挥主观能动性”。实际、规律和能动实践应当统一。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(679,49,'JUDGE','时间和空间是物质运动的存在形式。','TRUE','该说法正确。物质运动总在一定时间和空间中进行。',3,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(680,49,'JUDGE','意识能够脱离物质条件直接改变客观事物。','FALSE','该说法错误。意识须通过人的实践转化为现实力量。',3,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(681,50,'SINGLE','事物发展的根本原因在于什么？','C','正确答案是“事物内部矛盾性”。内部矛盾是事物发展的根本动力。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(682,50,'SINGLE','矛盾的两个基本属性是？','B','正确答案是“同一性和斗争性”。矛盾双方既相互依存又相互排斥。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(683,50,'SINGLE','辩证否定的实质是什么？','A','正确答案是“扬弃”。扬弃包含克服和保留两个方面。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(684,50,'MULTIPLE','联系具有哪些特点？','A,B,C','正确选项为“客观性、普遍性、多样性”。联系有条件且形式多样，不由主观任意设定。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(685,50,'MULTIPLE','矛盾普遍性和特殊性的关系包括哪些？','A,B,C','正确选项为“相互联结、在一定条件下相互转化、共性寓于个性之中”。一般与个别构成辩证统一。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(686,50,'MULTIPLE','关于量变和质变，下列说法正确的有？','A,B,C','正确选项为“量变是质变的必要准备、质变是量变的必然结果、质变为新的量变开辟道路”。发展体现量变与质变的相互转化。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(687,50,'JUDGE','新事物不可战胜，是因为它符合事物发展的必然趋势。','TRUE','该说法正确。新事物有新的结构和功能并得到进步力量支持。',3,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(688,50,'JUDGE','任何偶然现象都与必然性完全无关。','FALSE','该说法错误。必然性通过大量偶然性表现并为其开辟道路。',3,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(689,51,'SINGLE','检验认识真理性的唯一标准是？','A','正确答案是“实践”。实践把主观认识同客观结果联系起来。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(690,51,'SINGLE','感性认识的基本形式不包括哪项？','D','正确答案是“概念”。概念属于理性认识形式。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(691,51,'SINGLE','从感性认识上升到理性认识，首先要求什么？','C','正确答案是“占有丰富而真实的感性材料”。理性认识以可靠感性材料为基础。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(692,51,'SINGLE','真理的客观性是指什么？','B','正确答案是“真理内容不依人的意志为转移”。真理反映的对象和内容具有客观性。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(693,51,'MULTIPLE','实践在认识中的决定作用包括哪些？','A,B,C','正确选项为“是认识的来源、是认识发展的动力、是认识的目的”。认识产生、发展并最终服务于实践。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(694,51,'MULTIPLE','关于真理和价值，下列说法正确的有？','A,B,C','正确选项为“真理尺度要求符合客观规律、价值尺度体现主体需要、成功实践是真理尺度与价值尺度的统一”。合理实践必须兼顾规律和人民需要。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(695,51,'JUDGE','认识运动是实践、认识、再实践、再认识的循环上升过程。','TRUE','该说法正确。实践与认识反复深化并不断发展。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(696,51,'JUDGE','真理具有绝对性，因此任何具体真理都不需要发展。','FALSE','该说法错误。真理的绝对性与相对性相统一，具体认识需深化。',3,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(697,52,'SINGLE','社会存在中最基本、最具决定性的因素是？','C','正确答案是“物质生产方式”。生产方式制约社会生活的基本面貌。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(698,52,'SINGLE','生产力中最活跃的因素是？','B','正确答案是“劳动者”。劳动者使用生产工具作用于劳动对象。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(699,52,'SINGLE','上层建筑的核心是什么？','A','正确答案是“国家政权”。政治上层建筑以国家政权为核心。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(700,52,'SINGLE','社会基本矛盾是指哪两对矛盾？','D','正确答案是“生产力与生产关系、经济基础与上层建筑”。这两对矛盾贯穿社会发展过程。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(701,52,'SINGLE','人民群众创造历史的活动最基本体现在哪里？','C','正确答案是“生产实践”。物质生产是社会存在和发展的基础。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(702,52,'MULTIPLE','社会意识相对独立性表现在哪些方面？','A,B,C','正确选项为“与社会存在发展不完全同步、各种形式相互影响、可反作用于社会存在”。相对独立不等于绝对独立。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(703,52,'JUDGE','生产关系必须适合生产力状况，是社会发展的基本规律。','TRUE','该说法正确。生产力决定生产关系，生产关系又反作用于生产力。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(704,52,'JUDGE','历史人物可以随心所欲地决定社会发展的根本方向。','FALSE','该说法错误。人物作用受社会规律和历史条件制约。',3,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(705,53,'SINGLE','商品的二因素是？','A','正确答案是“使用价值和价值”。商品既能满足需要，又凝结无差别人类劳动。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(706,53,'SINGLE','具体劳动形成商品的什么？','D','正确答案是“使用价值”。具体劳动创造不同的有用属性。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(707,53,'SINGLE','货币的本质是什么？','C','正确答案是“固定充当一般等价物的商品”。货币从商品交换中分离并表现其他商品价值。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(708,53,'SINGLE','资本总公式的矛盾是指什么？','B','正确答案是“价值增殖与等价交换规律之间的矛盾”。剩余价值不能仅从流通领域的等价交换产生。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(709,53,'SINGLE','剩余价值的唯一源泉是什么？','A','正确答案是“雇佣工人的剩余劳动”。劳动力使用创造超过自身价值的价值。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(710,53,'MULTIPLE','劳动力成为商品的基本条件包括哪些？','A,B,C','正确选项为“劳动者有人身自由、劳动者没有别的商品可出卖、劳动者缺少实现劳动力所需生产资料”。自由而又缺乏生产资料使劳动者出售劳动力。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(711,53,'MULTIPLE','资本积累可能带来哪些结果？','A,B,C','正确选项为“资本有机构成提高、相对过剩人口形成、财富两极积累趋势”。积累扩大资本主义矛盾，并不自动消除危机。',3,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(712,53,'MULTIPLE','产业资本循环依次采取哪些职能形式？','A,B,C','正确选项为“货币资本、生产资本、商品资本”。三种职能形式对应购买、生产和销售阶段。',3,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(713,54,'SINGLE','毛泽东思想形成发展的时代主题是？','A','正确答案是“战争与革命”。近代中国革命处于帝国主义战争与无产阶级革命时代。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(714,54,'SINGLE','毛泽东思想达到成熟的主要时期是？','D','正确答案是“土地革命战争后期和抗日战争时期”。这一时期新民主主义革命理论得到系统阐述。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(715,54,'SINGLE','党的根本工作路线是？','C','正确答案是“群众路线”。一切为了群众、一切依靠群众是根本立场和方法。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(716,54,'MULTIPLE','毛泽东思想活的灵魂包括哪些？','A,B,C','正确选项为“实事求是、群众路线、独立自主”。三者贯穿毛泽东思想各组成部分。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(717,54,'MULTIPLE','实事求是要求做到哪些？','A,B,C','正确选项为“一切从实际出发、理论联系实际、在实践中检验和发展真理”。实事求是强调客观实际与科学理论统一。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(718,54,'MULTIPLE','毛泽东思想的历史地位包括哪些？','A,B,C','正确选项为“马克思主义中国化时代化的第一个重大理论成果、中国革命和建设的科学指南、中国共产党和中国人民宝贵精神财富”。其理论与实践价值具有整体和长远意义。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(719,54,'JUDGE','独立自主意味着拒绝一切国际交流与合作。','FALSE','该说法错误。独立自主强调立足自身，同时可平等开展合作。',3,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(720,54,'JUDGE','群众路线把人民群众看作历史创造者。','TRUE','该说法正确。路线坚持从群众中来、到群众中去。',3,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(721,55,'SINGLE','新民主主义革命的性质是？','C','正确答案是“无产阶级领导的资产阶级民主主义革命”。任务反帝反封建，领导力量是无产阶级。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(722,55,'SINGLE','新民主主义革命的首要对象是？','B','正确答案是“帝国主义”。帝国主义是近代中国贫困落后的总根源之一。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(723,55,'SINGLE','中国革命的基本问题是？','A','正确答案是“农民问题”。农民是革命主力军，土地问题是核心利益。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(724,55,'MULTIPLE','新民主主义革命的三大法宝是？','A,B,C','正确选项为“统一战线、武装斗争、党的建设”。三者是革命胜利的重要经验。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(725,55,'MULTIPLE','新民主主义革命的动力包括哪些？','A,B,C','正确选项为“工人阶级、农民阶级、城市小资产阶级”。民族资产阶级也有革命性，封建地主是革命对象。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(726,55,'MULTIPLE','建立革命统一战线的经验包括哪些？','A,B,C','正确选项为“坚持独立自主、发展进步势力、争取中间势力”。统一战线中须坚持无产阶级领导。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(727,55,'JUDGE','中国革命必须以武装斗争为主要形式，这是由近代中国国情决定的。','TRUE','该说法正确。反动统治依靠武装，革命需以革命武装反抗。',3,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(728,55,'JUDGE','新民主主义革命胜利后应长期停留在新民主主义社会。','FALSE','该说法错误。新民主主义社会是向社会主义过渡的社会形态。',3,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(729,56,'SINGLE','党在过渡时期总路线的主体是？','A','正确答案是“逐步实现社会主义工业化”。工业化是总路线主体，三大改造是两翼。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(730,56,'SINGLE','农业社会主义改造遵循的原则是？','D','正确答案是“自愿互利、典型示范和国家帮助”。这些原则保障合作化稳步推进。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(731,56,'SINGLE','对资本主义工商业实行和平赎买的高级形式是？','C','正确答案是“公私合营”。公私合营逐步把企业纳入社会主义改造。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(732,56,'SINGLE','社会主义基本制度在我国初步确立的标志是？','B','正确答案是“社会主义改造基本完成”。1956年三大改造基本完成改变了所有制结构。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(733,56,'MULTIPLE','社会主义改造的对象包括哪些？','A,B,C','正确选项为“农业、手工业、资本主义工商业”。三大改造针对生产资料私有制的主要领域。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(734,56,'MULTIPLE','我国社会主义改造的历史经验包括哪些？','A,B,C','正确选项为“社会主义工业化与改造并举、积极引导、逐步过渡、用和平方法改造”。改造结合国情采取渐进和平方式。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(735,56,'JUDGE','国家资本主义是改造资本主义工商业的一种过渡形式。','TRUE','该说法正确。从初级到高级形式逐步实现所有制转变。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(736,56,'JUDGE','社会主义改造基本完成后，我国仍以私有制经济为绝对主体。','FALSE','该说法错误。社会主义公有制已成为经济制度的基础。',3,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(737,57,'SINGLE','《论十大关系》的基本方针是什么？','C','正确答案是“调动一切积极因素为社会主义事业服务”。文章探索符合中国情况的建设道路。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(738,57,'SINGLE','社会主义社会基本矛盾的性质是什么？','B','正确答案是“非对抗性矛盾”。可通过社会主义制度自身调整完善解决。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(739,57,'SINGLE','正确处理人民内部矛盾的总方针是？','A','正确答案是“用民主的方法解决”。人民内部矛盾应采取讨论、说服和教育等方法。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(740,57,'SINGLE','走中国工业化道路必须处理好什么关系？','D','正确答案是“重工业、轻工业和农业的关系”。统筹产业关系有利于国民经济协调发展。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(741,57,'SINGLE','社会主义建设道路初步探索的重要意义之一是？','C','正确答案是“为中国特色社会主义道路形成提供经验和准备”。探索成果和教训都成为后续发展的重要基础。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(742,57,'MULTIPLE','初步探索形成的重要思想包括哪些？','A,B,C','正确选项为“正确处理十大关系、正确处理人民内部矛盾、走中国工业化道路”。前三项是结合中国实际形成的建设思想。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(743,57,'JUDGE','社会主义社会不存在任何矛盾。','FALSE','该说法错误。社会主义社会仍存在基本矛盾和各类具体矛盾。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(744,57,'JUDGE','探索中的经验和教训都能为后来改革发展提供借鉴。','TRUE','该说法正确。科学总结正反经验有助于认识建设规律。',3,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(745,58,'SINGLE','中国特色社会主义理论体系形成发展的实践基础是？','A','正确答案是“改革开放和社会主义现代化建设实践”。伟大实践不断提出并回答新的时代课题。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(746,58,'SINGLE','邓小平理论的精髓是？','D','正确答案是“解放思想、实事求是”。这一思想路线贯穿理论形成发展。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(747,58,'SINGLE','社会主义的根本任务是？','C','正确答案是“发展生产力”。发展生产力为共同富裕和全面进步奠定基础。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(748,58,'SINGLE','“三个代表”重要思想创造性回答的主要问题是？','B','正确答案是“建设什么样的党、怎样建设党”。理论聚焦新的历史条件下党的建设。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(749,58,'SINGLE','科学发展观的第一要义是？','A','正确答案是“发展”。科学发展观把发展作为解决中国问题的关键。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(750,58,'MULTIPLE','中国特色社会主义理论体系包括哪些重要理论成果？','A,B,C','正确选项为“邓小平理论、“三个代表”重要思想、科学发展观”。这些成果在改革开放新时期接续形成发展。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(751,58,'MULTIPLE','社会主义本质要求包括哪些？','A,B,C','正确选项为“解放和发展生产力、消灭剥削、消除两极分化、最终达到共同富裕”。社会主义本质兼顾生产力发展和共同富裕目标。',3,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(752,58,'MULTIPLE','科学发展观的基本要求涉及哪些？','A,B,C','正确选项为“全面发展、协调发展、可持续发展”。全面协调可持续构成科学发展的基本要求。',3,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(753,59,'SINGLE','新时代是我国发展新的什么？','A','正确答案是“历史方位”。新的历史方位标明党和国家事业所处时代坐标。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(754,59,'SINGLE','我国社会主要矛盾变化后，哪一基本判断没有改变？','D','正确答案是“我国仍处于并将长期处于社会主义初级阶段”。主要矛盾变化不改变基本国情和国际地位判断。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(755,59,'SINGLE','中国特色社会主义进入新时代的主要标志性依据是？','C','正确答案是“社会主要矛盾发生转化”。矛盾转化反映发展阶段和人民需要的新特点。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(756,59,'MULTIPLE','新时代的内涵包括哪些？','A,B,C','正确选项为“承前启后继续夺取中国特色社会主义伟大胜利、决胜全面建成小康社会并全面建设社会主义现代化强国、全国各族人民团结奋斗创造美好生活”。新时代面向民族复兴并为人类作出更大贡献。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(757,59,'MULTIPLE','社会主要矛盾变化反映了哪些事实？','A,B,C','正确选项为“人民美好生活需要日益广泛、发展不平衡不充分问题突出、我国生产力水平总体提高”。阶段性变化没有改变初级阶段基本国情。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(758,59,'MULTIPLE','理解新时代历史方位需要把握哪些维度？','A,B,C','正确选项为“历史发展连续性、新的实践要求、民族复兴进程”。新时代在历史连续中体现新的阶段特征。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(759,59,'JUDGE','社会主要矛盾变化意味着社会主义初级阶段基本国情已经改变。','FALSE','该说法错误。基本国情和最大实际仍未改变。',3,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(760,59,'JUDGE','新时代中国特色社会主义是党领导人民长期奋斗的接续发展。','TRUE','该说法正确。新时代建立在革命、建设和改革积累基础上。',3,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(761,60,'SINGLE','中国式现代化的领导力量是？','C','正确答案是“中国共产党”。党的领导决定中国式现代化根本性质和方向。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(762,60,'SINGLE','中国式现代化的中国特色不包括哪项？','B','正确答案是“两极分化的现代化”。共同富裕而非两极分化是鲜明特征。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(763,60,'SINGLE','中国式现代化创造了哪两种新形态？','A','正确答案是“人类文明新形态和现代化新道路”。它拓展了发展中国家走向现代化的途径。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(764,60,'MULTIPLE','中国式现代化的本质要求包括哪些？','A,B,C','正确选项为“坚持中国共产党领导、坚持中国特色社会主义、实现高质量发展”。和平发展而非扩张掠夺是本质要求。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(765,60,'MULTIPLE','推进中国式现代化需要正确处理哪些重大关系？','A,B,C','正确选项为“顶层设计与实践探索、战略与策略、守正与创新”。重大关系需系统统筹而非割裂对立。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(766,60,'MULTIPLE','中国式现代化坚持哪些价值取向？','A,B,C','正确选项为“人民至上、共同富裕、物质文明和精神文明协调”。现代化成果应更多更公平惠及全体人民。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(767,60,'JUDGE','中国式现代化等同于照搬西方现代化模式。','FALSE','该说法错误。它立足中国国情，具有自身特色和本质要求。',3,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(768,60,'JUDGE','走和平发展道路是中国式现代化的重要特征。','TRUE','该说法正确。中国不走殖民掠夺和对外扩张的老路。',3,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(769,61,'SINGLE','全面深化改革的出发点和落脚点是？','A','正确答案是“促进社会公平正义、增进人民福祉”。改革成果应更多更公平惠及人民。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(770,61,'SINGLE','全面深化改革的总目标包括完善和发展中国特色社会主义制度以及什么？','D','正确答案是“推进国家治理体系和治理能力现代化”。制度完善与治理现代化构成统一整体。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(771,61,'SINGLE','全面深化改革的重点是什么？','C','正确答案是“经济体制改革”。经济体制改革对其他领域改革具有牵引作用。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(772,61,'SINGLE','改革开放的生命是什么？','B','正确答案是“创新”。实践创新和制度创新推动改革不断深化。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(773,61,'MULTIPLE','全面深化改革应坚持哪些原则？','A,B,C','正确选项为“党的全面领导、以人民为中心、守正创新”。改革需加强系统集成和协同高效。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(774,61,'MULTIPLE','处理改革发展稳定关系，应做到哪些？','A,B,C','正确选项为“改革力度与发展速度相协调、社会可承受程度相统一、在保持稳定中推进改革发展”。三者应动态协调而非相互替代。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(775,61,'JUDGE','全面深化改革是有方向、有立场、有原则的。','TRUE','该说法正确。改革坚持中国特色社会主义方向和人民立场。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(776,61,'JUDGE','改革进入深水区后可以只推进单一领域而不考虑系统关联。','FALSE','该说法错误。深层改革更需要系统性、整体性和协同性。',3,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(777,62,'SINGLE','全面依法治国的根本保证是？','C','正确答案是“党的领导”。党的领导贯穿依法治国全过程各方面。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(778,62,'SINGLE','全面依法治国最广泛、最深厚的基础是？','B','正确答案是“人民”。人民是依法治国的主体和力量源泉。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(779,62,'SINGLE','中国特色社会主义法治体系的前提是？','A','正确答案是“完备的法律规范体系”。良法体系为法治实施提供规范基础。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(780,62,'SINGLE','维护社会公平正义的最后一道防线是？','D','正确答案是“公正司法”。司法裁判承担定分止争和权利救济职责。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(781,62,'SINGLE','法治国家、法治政府、法治社会建设应当怎样推进？','C','正确答案是“一体建设”。三者相互联系、相互支撑。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(782,62,'MULTIPLE','全面依法治国要求共同推进哪些？','A,B,C','正确选项为“依法治国、依法执政、依法行政”。依法治国、执政、行政共同推进。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(783,62,'JUDGE','坚持依法治国首先要坚持依宪治国。','TRUE','该说法正确。宪法是根本法，具有最高法律地位和效力。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(784,62,'JUDGE','依法治国意味着道德建设不再发挥任何作用。','FALSE','该说法错误。法治与德治相辅相成，应依法治国和以德治国结合。',3,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(785,63,'SINGLE','新发展理念中解决发展动力问题的是？','A','正确答案是“创新”。创新发展注重培育新动能。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(786,63,'SINGLE','新发展理念中解决发展不平衡问题的是？','D','正确答案是“协调”。协调发展处理区域、城乡和各领域关系。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(787,63,'SINGLE','新发展理念中体现人与自然和谐共生的是？','C','正确答案是“绿色”。绿色发展强调节约资源和保护环境。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(788,63,'SINGLE','新发展理念中解决发展内外联动问题的是？','B','正确答案是“开放”。开放发展统筹国内国际两个市场两种资源。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(789,63,'SINGLE','新发展理念中体现社会公平正义要求的是？','A','正确答案是“共享”。共享发展强调成果由人民共享。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(790,63,'MULTIPLE','贯彻新发展理念要求做到哪些？','A,B,C','正确选项为“完整把握、准确理解、全面贯彻”。五大发展理念相互贯通、相互促进。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(791,63,'MULTIPLE','高质量发展强调哪些转变？','A,B,C','正确选项为“质量变革、效率变革、动力变革”。高质量发展摆脱粗放扩张路径。',3,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(792,63,'MULTIPLE','构建新发展格局强调哪些？','A,B,C','正确选项为“以国内大循环为主体、国内国际双循环相互促进、提高经济循环质量”。新发展格局是开放的国内国际双循环。',3,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(793,64,'SINGLE','近代中国社会的两大主要矛盾是？','A','正确答案是“帝国主义和中华民族、封建主义和人民大众的矛盾”。两大主要矛盾决定近代革命任务。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(794,64,'SINGLE','近代中国革命的两大历史任务之一是争取民族独立和人民解放，另一项是？','C','正确答案是“实现国家富强和人民富裕”。两大任务相互区别又紧密联系。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(795,64,'MULTIPLE','近代中国半殖民地半封建社会的基本特征包括哪些？','A,B,C','正确选项为“帝国主义操纵经济政治命脉、封建剥削制度仍占优势、经济政治发展不平衡”。国家不独立且社会经济结构复杂落后。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(796,64,'MULTIPLE','帝国主义侵略中国的主要方式包括哪些？','A,B,C','正确选项为“军事侵略、政治控制、经济掠夺”。文化渗透也是侵略方式，目的并非帮助独立。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(797,64,'MULTIPLE','近代中国人民反侵略斗争的意义包括哪些？','A,B,C','正确选项为“打击侵略者野心、教育和锻炼人民、促进民族意识觉醒”。斗争积累力量，但早期未完成民族独立任务。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(798,64,'JUDGE','近代中国社会主要矛盾决定了反帝反封建的革命任务。','TRUE','该说法正确。社会性质和主要矛盾规定革命对象与任务。',3,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(799,64,'JUDGE','半殖民地意味着中国在近代已经完全沦为某一个国家的殖民地。','FALSE','该说法错误。中国保留形式主权但受到列强共同控制和侵略。',3,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(800,65,'SINGLE','太平天国农民战争提出的纲领性文件之一是？','C','正确答案是“《天朝田亩制度》”。《天朝田亩制度》反映农民平均土地愿望。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(801,65,'SINGLE','洋务运动的指导思想常被概括为？','B','正确答案是“中学为体、西学为用”。洋务派主张维护封建制度并学习西方技术。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(802,65,'SINGLE','戊戌维新运动的政治目标之一是？','A','正确答案是“实行君主立宪”。维新派试图通过改良建立资本主义君主立宪制度。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(803,65,'MULTIPLE','太平天国运动失败的原因包括哪些？','A,B,C','正确选项为“农民阶级局限性、缺乏科学理论指导、未能正确对待儒学和团结力量”。农民阶级自身无法提出完整科学纲领。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(804,65,'MULTIPLE','洋务运动兴办的事业包括哪些？','A,B,C','正确选项为“近代军事工业、近代民用企业、新式学堂”。洋务派还派遣留学生并筹建海军。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(805,65,'MULTIPLE','维新运动的积极意义包括哪些？','A,B,C','正确选项为“爱国救亡、政治改良探索、思想启蒙”。运动推动思想解放但未完成革命任务。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(806,65,'JUDGE','洋务运动的根本目的是维护清王朝统治。','TRUE','该说法正确。学习西方技术服务于“自强”“求富”和维护旧制度。',3,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(807,65,'JUDGE','戊戌维新运动依靠广泛发动工农群众取得了最终成功。','FALSE','该说法错误。维新派力量薄弱且脱离群众，运动很快失败。',3,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(808,66,'SINGLE','中国第一个全国性资产阶级革命政党是？','A','正确答案是“中国同盟会”。同盟会于1905年成立并形成全国性组织。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(809,66,'SINGLE','孙中山三民主义中的“民权”主要指？','D','正确答案是“建立资产阶级民主共和国”。民权主义以推翻君主专制、建立共和为内容。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(810,66,'SINGLE','武昌起义爆发于哪一年？','C','正确答案是“1911年”。武昌起义揭开辛亥革命高潮。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(811,66,'SINGLE','《中华民国临时约法》确立的国家政体原则是？','B','正确答案是“资产阶级共和国”。约法具有资产阶级共和国宪法性质。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(812,66,'MULTIPLE','辛亥革命的历史意义包括哪些？','A,B,C','正确选项为“推翻清王朝统治、结束君主专制制度、传播民主共和观念”。革命有重大功绩，但未完成反帝反封建任务。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(813,66,'MULTIPLE','辛亥革命失败的原因包括哪些？','A,B,C','正确选项为“没有提出彻底反帝反封建纲领、不能充分发动依靠人民群众、不能建立坚强革命政党”。资产阶级软弱性和妥协性制约革命。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(814,66,'JUDGE','辛亥革命结束了中国延续两千多年的君主专制制度。','TRUE','该说法正确。清帝退位和共和建立使君主专制制度终结。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(815,66,'JUDGE','辛亥革命完成了民族独立和人民解放的全部任务。','FALSE','该说法错误。社会性质和人民悲惨境遇未得到根本改变。',3,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(816,67,'SINGLE','五四运动的直接导火线是？','C','正确答案是“巴黎和会中国外交失败”。列强把德国在山东权益转给日本激起抗议。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(817,67,'SINGLE','中国共产党第一次全国代表大会召开于哪一年？','B','正确答案是“1921年”。中共一大宣告中国共产党正式成立。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(818,67,'SINGLE','中国共产党成立的思想基础是？','A','正确答案是“马克思主义在中国传播”。五四前后马克思主义广泛传播并同工人运动结合。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(819,67,'SINGLE','中国共产党成立的阶级基础是？','D','正确答案是“中国工人阶级成长壮大”。产业工人队伍发展为建党提供阶级条件。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(820,67,'SINGLE','党的二大首次明确提出什么革命纲领？','C','正确答案是“反帝反封建的民主革命纲领”。二大依据国情提出最低纲领。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(821,67,'MULTIPLE','五四运动的历史特点包括哪些？','A,B,C','正确选项为“彻底反帝反封建、群众基础广泛、促进马克思主义传播”。先进青年、工人阶级和广大群众共同推动运动。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(822,67,'JUDGE','中国共产党成立使中国革命有了坚强领导核心和科学指导思想。','TRUE','该说法正确。自此中国革命面貌焕然一新。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(823,67,'JUDGE','中国共产党的成立是偶然事件，与近代社会矛盾和工人运动无关。','FALSE','该说法错误。建党有深刻社会、阶级、思想和组织条件。',3,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(824,68,'SINGLE','中国人民抗日战争胜利的决定因素是？','A','正确答案是“中国共产党发挥中流砥柱作用”。党的政治领导和抗日民族统一战线发挥关键作用。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(825,68,'SINGLE','解放战争时期第二条战线主要是指？','D','正确答案是“国民党统治区的爱国民主运动”。学生和各阶层民主运动配合人民解放战争。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(826,68,'SINGLE','中华人民共和国成立于哪一天？','C','正确答案是“1949年10月1日”。开国大典宣告中华人民共和国中央人民政府成立。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(827,68,'SINGLE','新中国成立标志着什么革命取得基本胜利？','B','正确答案是“新民主主义革命”。反帝反封建的新民主主义革命任务基本完成。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(828,68,'SINGLE','中国革命胜利的基本经验之一是？','A','正确答案是“建立广泛统一战线”。统一战线、武装斗争、党的建设是三大法宝。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(829,68,'MULTIPLE','中国人民抗日战争胜利的意义包括哪些？','A,B,C','正确选项为“彻底粉碎日本军国主义殖民奴役图谋、促进中华民族觉醒和团结、为世界反法西斯战争胜利作出重大贡献”。抗战胜利未直接完成社会主义改造。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(830,68,'MULTIPLE','新中国成立的历史意义包括哪些？','A,B,C','正确选项为“结束帝国主义列强压迫和封建主义统治、人民成为国家主人、为实现民族复兴创造根本社会条件”。成立开启新纪元，但现代化仍需长期建设。',3,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(831,68,'MULTIPLE','中国革命胜利的主要原因包括哪些？','A,B,C','正确选项为“中国共产党的领导、马克思主义中国化理论指导、广大人民支持参与”。人民立场和正确领导是胜利根本保障。',3,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(832,69,'SINGLE','人生观主要包括人生目的、人生态度和什么？','A','正确答案是“人生价值”。三者相互联系构成人生观主要内容。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(833,69,'SINGLE','人生目的回答的根本问题是？','D','正确答案是“人为什么活着”。人生目的决定人生道路和态度。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(834,69,'SINGLE','人生价值内在包括哪两个方面？','C','正确答案是“自我价值和社会价值”。个人需要满足与对社会贡献相互联系。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(835,69,'MULTIPLE','积极进取的人生态度通常体现为哪些？','A,B,C','正确选项为“认真、务实、乐观”。正确态度要求面对实际、承担责任、创造价值。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(836,69,'MULTIPLE','评价人生价值应坚持哪些方法？','A,B,C','正确选项为“能力有大小与贡献须尽力相统一、物质贡献与精神贡献相统一、完善自身与贡献社会相统一”。社会贡献是根本尺度，评价还需全面具体。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(837,69,'MULTIPLE','反对错误人生观主要包括反对哪些？','A,B,C','正确选项为“拜金主义、享乐主义、极端个人主义”。前三者把金钱、享乐或私利绝对化。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(838,69,'JUDGE','个人对社会和他人的贡献是评价人生价值的重要方面。','TRUE','该说法正确。社会价值体现个人活动对社会需要的满足。',3,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(839,69,'JUDGE','实现人生价值可以完全脱离社会客观条件。','FALSE','该说法错误。价值实现既靠主观努力，也受社会条件制约。',3,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(840,70,'SINGLE','理想区别于空想的根本特征是？','C','正确答案是“具有实现可能性”。理想以现实规律和条件为基础并指向未来。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(841,70,'SINGLE','信念最集中、最高层次的表现形式是？','B','正确答案是“信仰”。信仰体现对最高价值和理想的坚定认同。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(842,70,'SINGLE','理想信念的作用不包括哪项？','A','正确答案是“代替全部实际行动”。理想必须通过实践奋斗才能实现。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(843,70,'MULTIPLE','理想信念具有哪些特征？','A,B,C','正确选项为“思想性与实践性、时代性与阶级性、多样性与共同性”。理想信念形成于具体社会历史条件。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(844,70,'MULTIPLE','正确认识理想与现实关系，需要把握哪些？','A,B,C','正确选项为“理想源于现实又超越现实、现实孕育理想发展条件、理想可通过实践转化为现实”。二者是对立统一关系。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(845,70,'MULTIPLE','大学生坚定理想信念应做到哪些？','A,B,C','正确选项为“立志高远、立志做大事、在实践中艰苦奋斗”。理想落实于服务社会的持续行动。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(846,70,'JUDGE','艰苦奋斗是实现理想的重要条件和根本途径。','TRUE','该说法正确。实践奋斗把理想转化为现实。',3,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(847,70,'JUDGE','理想越远大，就越不需要从具体小事做起。','FALSE','该说法错误。远大理想必须落实到脚踏实地的行动。',3,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(848,71,'SINGLE','爱国主义的基本要求不包括哪项？','A','正确答案是“排斥一切外来文明”。开放包容与爱国并不矛盾。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(849,71,'SINGLE','维护国家统一和民族团结是谁的根本利益所在？','D','正确答案是“中华民族”。统一团结是国家发展和人民幸福的重要保障。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(850,71,'SINGLE','新时代爱国主义的主题是？','C','正确答案是“实现中华民族伟大复兴的中国梦”。民族复兴凝聚爱国奋斗方向。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(851,71,'SINGLE','爱国主义在不同历史时期具有不同具体内容，说明它具有？','B','正确答案是“历史性”。爱国主义内涵随社会历史条件发展。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(852,71,'MULTIPLE','新时代爱国主义要求坚持哪些统一？','A,B,C','正确选项为“爱国和爱党统一、爱国和爱社会主义统一、维护祖国统一和民族团结”。当代爱国主义同中国特色社会主义实践紧密相连。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(853,71,'MULTIPLE','做忠诚爱国者应当如何行动？','A,B,C','正确选项为“维护国家根本利益、促进民族团结、尊重和传承中华优秀文化”。爱国行动必须理性、合法并服务共同利益。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(854,71,'JUDGE','经济全球化条件下国家仍然是民族存在和发展的基本组织形式。','TRUE','该说法正确。全球联系加深并未消除国家利益和主权。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(855,71,'JUDGE','爱国主义要求否定其他国家和民族的一切文明成果。','FALSE','该说法错误。真正爱国主义可尊重借鉴人类优秀文明成果。',3,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(856,72,'SINGLE','社会主义核心价值观社会层面的价值取向是？','C','正确答案是“自由、平等、公正、法治”。四项共同规范社会建设价值方向。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(857,72,'SINGLE','社会主义核心价值观公民层面的价值准则是？','B','正确答案是“爱国、敬业、诚信、友善”。四项体现公民应遵循的基本道德准则。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(858,72,'SINGLE','社会主义核心价值观的先进性主要体现在哪里？','A','正确答案是“它代表最广大人民的根本利益”。人民性和社会主义性质决定其先进性。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(859,72,'SINGLE','培育核心价值观的重要基础是？','D','正确答案是“中华优秀传统文化”。优秀传统文化提供深厚价值滋养。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(860,72,'SINGLE','核心价值观落细落小落实的关键环节是？','C','正确答案是“日常实践”。价值认同需转化为具体行为习惯。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(861,72,'MULTIPLE','社会主义核心价值观国家层面的目标包括哪些？','A,B,C','正确选项为“富强、民主、文明”。诚信属于公民个人层面。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(862,72,'JUDGE','社会主义核心价值观三个层面的内容相互联系、相互贯通。','TRUE','该说法正确。国家、社会和个人价值要求构成统一整体。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(863,72,'JUDGE','培育社会主义核心价值观只需要知识记忆，与实际行动无关。','FALSE','该说法错误。应在认知认同基础上通过实践养成。',3,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(864,73,'SINGLE','我国宪法的基本原则之一是？','A','正确答案是“党的领导”。党的领导是中国特色社会主义最本质特征。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(865,73,'SINGLE','我国宪法明确规定国家的一切权力属于谁？','D','正确答案是“人民”。人民主权是宪法基本原则。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(866,73,'SINGLE','法律权利和法律义务的关系是？','C','正确答案是“相互依存、相互统一”。权利实现离不开义务履行，二者互为条件。',1,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(867,73,'SINGLE','法律运行的起始性和关键性环节是？','B','正确答案是“法律制定”。立法把意志和利益转化为普遍行为规范。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(868,73,'SINGLE','法治思维首先要求树立什么意识？','A','正确答案是“法律至上”。法律至上强调宪法法律权威不可任意突破。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(869,73,'MULTIPLE','中国特色社会主义法治道路应坚持哪些？','A,B,C','正确选项为“党的领导、人民主体地位、法律面前人人平等”。党的领导、人民当家作主和依法治国有机统一。',2,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(870,73,'MULTIPLE','公民行使法律权利时应遵循哪些要求？','A,B,C','正确选项为“依法行使、正当行使、不得损害国家社会和他人合法权益”。权利有边界，应依照法定目的和方式行使。',3,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(871,73,'MULTIPLE','尊重和维护法律权威要求做到哪些？','A,B,C','正确选项为“信仰法律、遵守法律、服从依法作出的决定”。维护权威依靠认同、遵守和依法维权。',3,1,1,'2026-10-08 20:56:32','2026-10-08 20:56:32'),(928,34,'SINGLE','Choose the sentence with correct subject-verb agreement.','C','正确答案是“The data indicate a steady rise.”。In formal usage, data is treated here as plural and takes indicate.',1,1,1,'2026-10-08 20:57:45','2026-10-08 20:57:45'),(929,64,'SINGLE','鸦片战争后，近代中国逐步形成的基本社会性质是？','D','正确答案是“半殖民地半封建社会”。鸦片战争后中国社会性质逐步发生根本变化。',1,1,1,'2026-10-08 20:57:45','2026-10-08 20:57:45'),(946,3,'SINGLE','某计算机采用字节编址，指令长度为 32 位。某条相对寻址的转移指令占 4 字节，其地址字段为 8 位带符号整数（采用补码表示）。若该指令的起始地址为 1000H，地址字段内容为 FCH，则转移目标地址为（ ）。','B','相对寻址的目标地址 = PC + 偏移量。取指后 PC = 1004H，8 位补码 FCH 表示 −4，因此目标地址 = 1004H − 4 = 1000H。\n考查知识点： 相对寻址、PC 的变化、补码运算。',2,1,1,'2026-10-14 18:18:10','2026-10-14 18:18:10'),(947,3,'SINGLE','某计算机指令字长为 16 位，采用定长操作码，操作码字段占 6 位，每个地址字段占 5 位。若指令系统采用双地址指令格式，则该格式最多可以表示的不同指令条数为（ ）。','C','操作码占 6 位，可表示 \\(2^6=64\\) 种不同操作。两个地址字段共占 \\(5\\times2=10\\) 位，加上操作码的 6 位，恰好为 16 位，因此最多可以表示 64 种不同指令。\n考查知识点： 指令格式、定长操作码、操作码编码能力。',2,1,1,'2026-10-14 18:18:10','2026-10-14 18:18:10');
/*!40000 ALTER TABLE `question` ENABLE KEYS */;
UNLOCK TABLES;
DROP TABLE IF EXISTS `question_option`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `question_option` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '选项ID',
  `question_id` bigint NOT NULL COMMENT '所属题目ID',
  `option_key` varchar(10) NOT NULL COMMENT '选项标识：A/B/C/D',
  `content` text NOT NULL COMMENT '选项内容',
  `sort_order` int NOT NULL DEFAULT '0' COMMENT '排序',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_question_option_key` (`question_id`,`option_key`),
  KEY `idx_option_question` (`question_id`),
  CONSTRAINT `fk_option_question` FOREIGN KEY (`question_id`) REFERENCES `question` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=3698 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='题目选项表';
/*!40101 SET character_set_client = @saved_cs_client */;

LOCK TABLES `question_option` WRITE;
